INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p389994-me398', 'stk-jotun', 'ME 398', 'info', '{"desc": "http://img23.imageshack.us/img23/2664/coopl.jpg\n\nJotun is looking for Co-op Trainees in the following Majors:\n\n**\\(1\\) Industrial engineer in Yanbu.****\\(1\\) Chemical engineer in Jeddah or Yanbu.****\\(1\\) Mechanical engineer in Yanbu.****\\(1\\) Accountant in Jeddah.****\\(1\\) HR position in Jeddah \\(Industrial Engineer, Marketing or Management\\).** We offer:\n\n- A professional working environment that focuses on continuous improvement and innovation.\n\n- An international corporate culture founded on our four values; Loyalty, Care, Respect and Boldness.\n\n- Contract for each student with a monthly salary of SR 3000 (Basic Salary: 2400, Housing Allowance: 500 and Transportation Allowance: 100).\n\n- Prepared Co-op plan for each position.\n\n- Working hours 7:30 AM to 5:00 PM from Saturday to Wednesday.\n\n- Trainees will perform On-Job projects during the Co-op Period.\n\n- One week vacation will be given during the Co-op\n\nIn addition, competent trainees will have an opportunity to Join our family after graduation.\n\nC.V.s will be received & Exams will be held during the Career Day Event on 12-16 April.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-opportunities-in-jotun/72286/1", "user": "JOTUN", "ts": 1239280300000, "tid": 72286, "pn": 1}}', 1239280300000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p589122-me398', 'stk-user4727', 'ME 398', 'info', '{"desc": "طيب يا جماعة الخير … في يوم المهنة … ما هي الشركات التي من الممكن أن ترحب بي كطالب معدله أقل من 2.5 ومن الممكن أن أجري مقابله معها ؟؟\n\nوسؤال آخر: هل من الممكن أثناء دراستي وخصوصاً فترة ما قبل التطبيق أن أزور بعض الشركات التي من الممكن أن تأخذ الطلاب أصحاب المعدلات أقل من 2.5 وأن أقدم للعمل التعاوني معهم وبذلك تزيد فرصتي في التوظيف في هذه الشركة إن قبلتي في البرنامج التعاوني ؟؟\n\nوأخيراً: بالنسبة للتطبيق في أرامكو لمن معدلاتهم أقل من 2.5 … هل أستطيع مثلاً إن تم قبولي في برنامجها التعاوني أن أبذل طاقات في التطبيق وأن أنال إعجاب المشرف أو المدير الذي يرأسني ومن ثم يتم ترشيحي للعمل في هذا القسم في أرامكو ؟؟\n\nأتمنى الرد وسأكون لكم من الشاكرين\n\nأخوكم/ ميكانيكي مربوش\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-5/84811/23", "user": "user4727", "ts": 1271092949000, "tid": 84811, "pn": 23}}', 1271092949000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483097-me398', 'stk-abus3od', 'ME 398', 'info', '{"desc": "عليكم السلام\n\nاذا مقابلتك فالدمام الصناعية الثانية فالدمام فاللي بيسوي معك المقابلة مدير الموارد البشرية شمري ومعاه السكرتيره تكتب ملاحظات\n\nمقابلتي كانت على التدريب التعاوني عندهم وكانت سهلات بالانجليزي تكلم عن نفسك ومشروعك ,وليه معدلك نازل فالدبلوم وعالي فالبكالوريوس ووش تعرف عن الشركة وسالني اسالة بيسك عن الكهرباء بما ان تخصصي يندرج فالكهرباء زي وش قاونون اوم , حالة التيار في حال كانت الدائرة توازي او توالي, قوانين CDR , VDR , KVL وسألني وش الحساسات اللي ممكن موجودة على خط الانتاج (Ultra sonic, proximity) ولما خلصت المقابلة قال خلاص عديت مبروك\n\nومثل ماقلت المقابلة كانت للتطبيق عندهم ويمكن تختلف اذا كانت توظيف مادري\n\nعموما اذا تخصصك ميكانيكا توقع 95% بتجيك اسالة تكنيكال راجع زين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/al-qaryan/178052/2", "user": "abus3od", "ts": 1510155484000, "tid": 178052, "pn": 2}}', 1510155484000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1507437-me398', 'stk-engabdullah00', 'ME 398', 'info', '{"desc": "بالنسبة لشركة ال السالم انا سويت فيها تدريب تعاوني وفي نهاية التدريب السوبر فايزر ارسل ركمنديشن للمدير بالنسبة للتوظيف وكانو منزلين وظيفة مهند ميكانيكي بس الله ماكتب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181191/4", "user": "Engabdullah00", "ts": 1552927064000, "tid": 181191, "pn": 4}}', 1552927064000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1232307-me398', 'stk-som3aa', 'ME 398', 'info', '{"desc": "صحيح و معناها Employee Relations & training\nبس السؤال ايش علاقه قسم اداري يختص بتدريب الموظفين بالهندسه الميكانيكية ؟؟\nالمكتوب عادةأ يبان من عنوانه , شكلي بعد التدريب هشارك في موضوع (ال coop مجرد نكته) ههههههههههههههه\nاتمنى اذا فيه احد عنده أي معلومه او شي يخص ها القسم ياليت يتكرم وينورنا 🤠\nو مشكور يالطيب على ردك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/145654/6", "user": "som3aa", "ts": 1370469464000, "tid": 145654, "pn": 6}}', 1370469464000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1014674-me398', 'stk-dr_k_a_z', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nصباح الورد عالجميع\n\nتعرفون بقي كم يوم على الديد لاين للريبورت الاول …\n\nانا ميكانيكال والكواب تبعي بارمكو …\n\nالمشكلة مو عارف ابدا كتابة الريبورت … انا عندي معلومات تكنكال كثير واستفدت الكثير خلال المدة الماضية ولله الحمد وكل المعلومات اللي عندي كاتبها على شكل بوينتز …\n\nوكمان يعني اشتغلت واستفدت معلومات في تخصصي وفي الالكتريك والكيميكال كمان.\n\nفكل اللي حاب اعرفة\n\nاش الفورمات تبع الريبورت ؟؟؟؟\nاش اكتب واش اللي اسويله اقنور ؟؟؟\nهل اكتب الريبورت (by weeks ) >>>يعني في الاسبوع الاول سويت كذا والثاني كذا …\nوالا اكتبه ( by units ) >>> يعني في اليونت الفلانية سويت كذا واليونت الثانية كذا وكذا …\nوالا اكتبه ( by work ).\n\nاتمنى ان اللي عنده خبرة او معلومة يشاركنا\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-progress-report-1/123497/1", "user": "Dr_k_a_z", "ts": 1332647489000, "tid": 123497, "pn": 1}}', 1332647489000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p523176-me398', 'stk-thamer_al-fakeeh', 'ME 398', 'info', '{"desc": "Internship &Coop:\nAn internship or co-op at GE gives a student hands-on experience,\nworking on challenging projects with some of the best minds in business. This is a superb opportunity to give his career a head start while making valuable Contacts. The Coop work experience is a vitally important tool for helping a student determines the course of his career, giving him valuable insight into the workplace, useful experience, and helpful contacts for the future.\n\nIf your Major is: Electric Engineering, Mechanical Engineering, Industrial Engineering, or Finance, you may apply through this link:\n\nhttp://www.ge.com/careers/students/internships/middle_east.html\n\nGE invests over $1 billion in training & development. You’ll never stop learning and growing, because GE is a culture committed to education. We’re NOT training Employees; we’re DEVELOPING talent !\n\nRegards,\nThamer Al-Fakeeh\nHR Manager\nGE Energy & Water\nMiddle East & Africa", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/internship-opportunities-with-ge/82198/1", "user": "Thamer_Al-Fakeeh", "ts": 1263459213000, "tid": 82198, "pn": 1}}', 1263459213000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1242043-me398', 'stk-nes13ta', 'ME 398', 'info', '{"desc": "الاخ صبعبلي الاخوان ما قصروا كفو و وفو .\n\nالاخ بسطويسي عانيت م مشكلتك انا في الكوأب\n\nبما انك تشتغل ك كيميائي وانت كيميكال انجنير فلا اعتقد انه مناسب انك تكتب عن شغلك في الاب\n\nاطب من مديرك يحولك ع قسم اخر تحصل فيه كيس ستدي\n\nاو على الاقل …\n\nذكرت حاجة عن السكيلنق الي هو السائل الي يبقا في البايبز بامكانك تاخذها ك كيس ستدي\n\nو من الفلويد ميكانيكس راح تبدا …\n\nرأي شخصي متواضع … كل التوفيق لكم اخواني", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/case-study/146357/8", "user": "nes13ta", "ts": 1372856910000, "tid": 146357, "pn": 8}}', 1372856910000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1478467-me398', 'stk-instrument', 'ME 398', 'info', '{"desc": "وعليكم السلام ورحمة الله\nالله يعطيك العافية\nمعلومات ممتازة لكن سويت مقابلة مع ادرة المشاريع عندهم قبل ردك وماكنت عارف عن الشركة شي لكن مدير مشروع اعطاني فكرة بسيطة عن الشركة والشركة تتبع مجموعة الراشد وبعد يقول ان المشاريع او الشغل مافي واجد!\nتقريبا ساعه سواليف\nبعد هالساعة قالي كلم بالجوال كلمني سعودي مدير مدير المشروع على كلام مدير المشروع\nس1.\nايش وداك الصين؟ :office_worker:\nس2.\nتشتغل بالحد الجنوبي :ninja:\nوشوي دردشة بشكل ودي\nبعدين قالي خلاص بنودي اوراقك الى الاتش ار غدا\nاعطوني اربع اوراق قالو عبيها وجيبها اليوم الثاني\n\nاليوم الثاني قبل ماروح اودي اوراقي وشهاداتي, اتصل علي مدير المشروع العربي وقال كم تبغ راتب,قلت بما انه على قولك الشغل ماش والوضع لك عليه اساسي8000 اعتقد مقبول عندي\nقال شو قليل هذا في حقك 😍\nالمهم واكتب في النموذج الراتب المتوقع 13800 اساسي 🤠\nورحت له المكتب واعطية الاراق والشهادات وقاعد يتفحص في الاوراق الي وهو يقولي لي كاتب13800 ووجه كنه متمعر 😞:santa_1:\nانا انخرشت منه وطوالي مخرج7\nقلت قصدي مع البكج كامل 😡\nقلت خليني اغيره\nقال لا خلاص خليه كذا :zipper_mouth_face:\nوشكله بيمسكني الكوبري المعلق!\nالمهم اتوقع والله اعلم سوف استبعد علشان الراتب والحمدلله على كل حال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-s-e-m/177343/4", "user": "Instrument", "ts": 1502549078000, "tid": 177343, "pn": 4}}', 1502549078000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1441794-me398', 'stk-user8581', 'ME 398', 'info', '{"desc": "شفت فيه تقديم لفرصتين كواب في سابك لكن ما ادري اذا هو مفتوح للطلاب السعودين او لا فياليت الي عنده فكرة عن الموضوع او تواصل معهم يفيدنا ويصحح لي لو كنت غلطان\n\nعلى العموم الفرصتين المتاحتين هم في امريكا\nاول شي ادخل على هذا الرابط وسو حساب\nCurrent Vacancies | ظˆط¸ط§ط¦ظپ ط´ط§ط؛ط±ط© | ط§ظ„ط£ظ…ط±ظٹظƒطھظٹظ† | ط§ظ„ظˆط¸ط§ط¦ظپ | ط³ط§ط¨ظƒ\n\nتالي Search openings\nوابحث عن Co-op وراح تظهر لك فرصتين وراح يكون التدريب في امريكا …الفرصة الأولى في Indiana والثانية في Alabama\n\nوهذي المتطلبات في الفرصة الأولى\n\n[table=“width: 92%, align: center”]\n\n[td=“colspan: 2”]https://sjobs.brassring.com/TGWebHost/images/pixel.gif\n\nPosition Title\n[td=“class: tgalignleft, width: 80%”]Early Identification Program (EID/Co-op)\n\nAuto Req ID\n[td=“class: tgalignleft, width: 80%”]6757BR\n\nRe******** Assistance\n[td=“class: tgalignleft, width: 80%”]Yes\n\nRegion/Pole\n[td=“class: tgalignleft, width: 80%”]Americas\n\nFunctional Work Area\n[td=“class: tgalignleft, width: 80%”]Engineering\nManufacturing\n\nJob Purpose & Responsibilities\n[td=“class: tgalignleft, width: 80%”]At SABIC, we provide exceptional opportunities for engineering students to spend a semester doing real engineering work. Whether it’s in Operations, EHS&S, or Reliability, SABIC offers an array of different opportunities to help students develop the skills needed for a career after graduation.\n\nSABIC EIDs will work on meaningful projects that have real impact for the business under the guidance of some of our best engineers. They will receive on the job training, exposure to different parts of the business and mentoring from members of our leadership teams. In addition, they will build support networks with other EIDs and have the opportunity to be part of a pipeline into the SABIC Engineering Early Development Program (SEED) – a two year rotational program consisting of four, 6 month roles and two geographical ********s.\n\nDuring the program, EIDs will be assigned to experience the following types of assignments:\n\nChemical Operations;\n\nCompounding;\nReliability;\nEnvironmental, Health, and Safety.\nProgram placements will be based on technical development needs, availability of assignments and personal preference. Pay is competitive and re******** is available for those qualify.\n\nRequirements\n[td=“class: tgalignleft, width: 80%”]Requirements:\n\nPursuing a Chemical or Mechanical Engineering Degree with a 3.0/4.0 GPA\n\nEligibility Requirements:\n• You must submit your application for employment online to be considered. Please submit your resume using the apply online option on this page.\n• You must be 18 years or older\n• You must be willing to take a drug test as part of the selection process\n• You must be willing to submit to a background investigation as part of the selection process\n• You must have unrestricted authorization to work in the United States\n\nFor U.S. employment opportunities, SABIC Innovative Plastics hires U.S. citizens, permanent residents, asylees, refugees, and temporary residents. Temporary residence does not include those with non-immigrant work authorization (F, J, H or L visas), such as students in practical training status. Exceptions to these requirements will be determined based on shortage of qualified candidates with a particular skill. SABIC Innovative Plastics will require proof of work authorization prior to employment.\n\nCountry\n[td=“class: tgalignleft, width: 80%”]United States of America\n\nCity\n[td=“class: tgalignleft, width: 80%”]Evansville\n\nState/Province\n[td=“class: tgalignleft, width: 80%”]Indiana (IN)\n\nGeneral\n[td=“class: tgalignleft, width: 80%”]People Who Can\n\nWe’ve always believed that it takes special people to make a difference. They need ingenuity, brilliance and the freedom to turn their ideas into reality. At SABIC, this is our culture. We find open-minded, gifted and questioning people. Then we create the conditions for their talent to flourish: fulfilling work environments, state-of-the-art technology and the empowerment they need. So when you work for SABIC, you’re the person who can find new solutions and possibilities that change the world for the better.\n\nSABIC, headquartered in Riyadh (Saudi Arabia), is one of the world’s leading manufacturers of chemicals, fertilizers, plastics and ****ls. We supply these materials to other companies, who use them to make products on which the world has come to depend. At SABIC, we believe in using chemistry to power the ambitions of our customers, business partners, employees and societies we live in. We call this “CHEMISTRY THAT MATTERS™”.\n\nIn the Americas, SABIC employs over 5,000 people and is running 17 manufacturing sites, 5 technology and innovation centers. We are present in 7 countries with 17 offices. Major ********s within our broad network of innovation, production and marketing are: Evansville (IN, USA), Houston (TX, USA), Pittsfield (MA, USA) and Selkirk (NY, USA). With the acquisition of GE Plastics in 2007 we are a key producer of engineering thermoplastic resins, films and sheets. Discover more at sabic.com/careers\n\nAs an Equal Opportunity Employer, SABIC will not discriminate in its employment practices, including recruiting and hiring practices, based on an applicant’s race, color, religion, national origin, sex, sexual orientation, age, disability, veteran status, marital status, genetic information or other category protected by law.\n\nDisclaimers (USA):\n\nSABIC is not accepting unsolicited assistance from search firms/employment agencies for this employment opportunity. Please, no phone calls or emails to any employee of SABIC about this opening. All resumes submitted by search firms/employment agencies to any employee at SABIC via-email, the Internet or in any form and/or method without a valid written search firm agreement in place for this position will be deemed the sole property of SABIC; no fee will be paid in the event a candidate is hired by SABIC as a result of the unsolicited referral or through other means.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/53", "user": "user8581", "ts": 1455145184000, "tid": 170272, "pn": 53}}', 1455145184000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1174637-me398', 'stk-user5643', 'ME 398', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nفي بداية الترم اللي يسبق الكوأب\n\nروح الرابط هذا\nhttp://www2.kfupm.edu.sa/me/Guidelines%20ME%20COOP%20Program.pdf\n\nو اطبع صفحة 15 … و عبي الصفحه و وديها للـ Academic Adviser\nيوقعها لك\n\n( بعد ما تتأكد انك انهيت متطلبات الكوأب و ان شروط التطبيق اللي في الصفحه الرابعه في الرابط اللي فوق تنطبق عليك ) …\n\nبعدين ود الفورم للـ COOP COORDINATOR\n\nبعدها هو بيقولك روح لـ إدارة التدريب … انت روح لهم بيعطونك فورمين صورهم و خلهم معك …\n\nواحد من الفورمين للتقديم على الشركات …\n\nطبعا انت تقدر تقدم على الشركات اللي انت تبيها بلحالك … قدم على موقعهم او ايميلهم\n\nلكن مثلا اللي يبي يطبق في ارامكو …لازم ينتظر الجامعه تفتح التطبيق عن طريق موقعها ( راح يرسلون لك ايميل كل ما تجي شركه للتطبيق ))\n\nاما طلاب الـ ساينس اللي يبون يطبقون في ارامكو يقدمون عن طريق موقع ارامكو و الجامعه ما لها دخل …\n\nفيه شركات مثل شركة الكهرباء و شنايدر الكتريك ممكن انت تقدم عليها عن طريق الموقع على طول … لكن شركات ثانيه زي ارامكو ما ينفع تقدم الا عن طريق الجامعه …\n\nطبعا وقت التسجيل و بعد ما تاخذ الابرفال من ادفايزرك سجل الكورسين me351 & me 350 ( واحد في الصيف وواحد في الترم العادي )\n\nلا تفوتون يوم المهنه لانك ممكن تلقى شركات كثير تاخذك تطبق عندها\n\nهذا ملف من الجامعه حلو انك تقراه عن التطبيق\n\nhttp://www2.kfupm.edu.sa/stutraining/files/coop_guidelines.pdf\n\nو هذا موقع إدارة التدريب فيه معلومات عن التدريب التعاوني و معلومات عن بعض الشركات و الرواتب اللي تعطيها لطلاب الكوأب\nhttp://www1.kfupm.edu.sa/studentaffa...coop/Index.htm\n\nطبعا خلال التطبيق مطلوب منكم 3 ريبورتات و هذي امثله عليها\n\nFirst Progress Report\nhttp://www.m5zn.com/d/?14416022\n\n2nd Progress Report\nhttp://www.m5zn.com/d/?14416023\n\nFinal Progress Report\nhttp://www.m5zn.com/d/?14416024\n\nبالنسبه للـ COOP Plan لا تشيل همها لانها مجرد فورم تعبيه لك الشركه\n\nفكرة الموضوع من الاساس اني اعطيكم امثله لريبورتات ممتازه … اما الخطوات اللي ذكرتها هي اجتهاد مني … اللي حاب يضيف عليها او يعدل عليها حياه الله\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/139645/1", "user": "user5643", "ts": 1359733729000, "tid": 139645, "pn": 1}}', 1359733729000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1505748-me398', 'stk-user9946', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nاخواني انا محتار وين اتدرب فيه وماهي هي افضل الشركات للتدريب التعاوني(7 شهور) ونا قدامي خيارين\nالاول اني اتدرب بنفس منطقتي ولكن ما فيه شركات ممتازة\nالثاني اني اروح لشركة خارج المنطقة\nو الشركات خارج المنطقة واجد فيه منها شركات النفط (قطاع البترول والبتروكيماويات )و شركات انتاج الطاقة و شركات انتاج المواد الاساسية من النفط و شركات الطيران و شركات انتاج معدات ثقيلة و شركات التكييف يورك و GE و شركات السيارت\nو شركات كثير ولا اعلم ما اختار\n\nانا ارغب في شركه اتدرب فيها وبعد ما اتخرج واقدم على الوظائف استفيد منها في التقديم بحيث تكون في تخصصي ومرغوبه\n\n…\nوانا رحت للمسؤول عن التدريب التعاوني في كليتي وذكر لي شركات\nو المعهد العالي للمطاط بينبع ولا اخترت شي من اللي ذكر\nثم قالي شف الشركة اللي انت تبيها ونراسلهم لك\n\nولاني معطيه اسم شركة الا بعد ما اخذ رايكم\n\nالتخصص : هندسة ميكانيكية (علوم الميكانيكا )\nالمعدل : 3.1 من 5\n\nيهمني ان يكون لي سكن من الشركه\n\nواي معلومة عن التدريب التعاوني في الشركات ترها تفيدني\n\n*جامعتي ليست البترول والمعادن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/180992/1", "user": "user9946", "ts": 1549374542000, "tid": 180992, "pn": 1}}', 1549374542000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1113567-me398', 'stk-metallic', 'ME 398', 'info', '{"desc": "A- Have completed 85 credit-hours or more of his study\n\nB- Earned Cumulative and Major GPA of 2.0 or above\n\nC- Have passed the following courses\n\na. XXX 1xx All required level 1 courses\nb. ME 2xx All required level 2 ME courses\nc. ME 307 Machine Design I\nd. ME 309 Mechanics of Machines\ne. ME 315 Heat Transfer\nf. ENGL 214 Technical Report Writing\n\nالمصدر\nPage 4\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/134276/2", "user": "METALLIC", "ts": 1352281189000, "tid": 134276, "pn": 2}}', 1352281189000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1465045-me398', 'stk-_al-hero', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nانا طالب هندسة ميكانيكية وقبلتني شركة هيليبرتون لل Coop\nفيا ريت تفيدونا بخبراتكم\n\nالسنة :\nالتخصص :\nمكان التدريب + القسم :\nالمكافأة :\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة,… )\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/175609/1", "user": "_Al-hero", "ts": 1482405836000, "tid": 175609, "pn": 1}}', 1482405836000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p591980-me398', 'stk-user6783', 'ME 398', 'info', '{"desc": "السلام عليكم و رحمه الله و بركاته\n\nكيف حال العطله القصيره معكم << تصدقون أنها سبعه أيام فقط << الذكي يعرف ليه كتبت الجمله هذي 😊\n\nالمووووووهم\n\nهي دعوه لمناقشه مسأله عويصه شوي و مجموعه من الأفكار الموجوده في رأسي و رأس غيري حول موضوع التدري التعاوني ((coop )) , خلونا نفترض بالبدايه ان فيه شركه اسمها شركه الهضاب لتفصيل الثياب بطرق ميكانيكيه بحته << طبعا لتسهيل الأسئله\n\nس1- ما المطلوب مني قبل قدوم موعد التسجيل للبرنامج ؟؟\n\nس2- كيف أسجل في البرنامج وقت التسجيل ؟؟ << متعودين على تسجيل المواد العاديه\n\nس3- كيف يتم اختيار الشركه ؟\n\nس4- كيف اسجل في شركه الهضاب أو أي شركه غيرها ما هي مذكوره في قائمه الجامعه ؟\n\nس5- ما هي الورق المطلوب مني تحضيرها علشان اطبق في شركه الهضاب أو غيرها من الشركات الغير مذكوره في قائمه الجامعه ؟\n\nس6- متى أحتاج أنهي الأجراءات للأنضمام لشركه الهضاب ؟\n\nس7- << يا حبني لرقمن لبسته من سنين , , , كنه ولد عمي و لا ولد خالي 😆\n\nو اللي عنده أسئله يتوقع ان الموضوع ما غطاها يكتبها , بالمناسبه أنا ميكانيكالاوي << على وزن السهلاوي 😏\n\n--------------------\nبانتظار أجاات شافيه و وافيه << على الطاري شافي لاعب مصر صحيح وقع عقد مع الانتر و الحاجه الثانيه مطعم وافي اللي بالسيتي سنتر بالبحرين يبيع شوربه خضار و لا لا 🤣\n--------------------", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/87052/1", "user": "user6783", "ts": 1271759014000, "tid": 87052, "pn": 1}}', 1271759014000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p60564-me398', 'stk-redeemer', 'ME 398', 'info', '{"desc": "السلام عليكم أخواني\n\nكيف حالكم عساكم بخير عسى مابوه خبيث<<<---أقول إخلص 😠\n\nمالكم بالطويلة,إحم\n\nحالياً أطبق بالرياض من الصيف اللي طاف في (يحتفظ العضو باسم المنشأة:D )\nطبعاً مابي أقول لكم كيف إتنكبت فيهم شر نكبة وكلامهم عند المقابلة غير والواقع غير,ومن الأول كيف عارضين عند الجامعة راتب 4000 ريال ولمن جيت قالوا لي لك 2500 ريال وقالوا لواحد ميكانيكل لك 2000 ريال بس.\n\nالشغل هنا ميييح ماكو شغل بالمرة لمجال تخصصي التسويق MKT .\nكلمت الأدفايزر قالي حاول ترص ع المسؤول لازم يشوف لك شغلة ولا كان ماطلبوا من الأساس يبون طالب تسويق.\n\nالقهر الكوأب بيخلص ولحد الحين أعصر مخي أبي أشوف حاجة أكتب فيها البلية الريبورت مافيه 😦\n\nعلشان يشغلني المسؤول هنا قام يعطيني شغلات مال أمها داعي بالتخصص وحاجات تافهة,من ضمنها يبيني أعمل خطوات إعداد ورشة عمل متكاملة.\n\nياهوو يابو الشباب وشو أسوي لك ورشة عمل خطواتها وأنا ماعمري طبيت في هالمجال وأصلاً مادرسناها ولا لي شغل فيه…القهر قالها لي إنهم بيتعاونوا مع شركة متخصصة في إدارة ورش العمل,يعني تزحمني ليش طيب,\n\nكتبت وسويت اللي أقدر عليه ورسلته له بالإيميل,المدير والمسؤول مسافرين بالخارج لغرض الشغل إسبوع وراجعين,اليوم الأحد تجيني رسالة من عند المسؤول وهو بالخارج أنقلها لكم:\n\nالاستاذ *******\nتحية طيبة\nوصلتني عناصر ورشة العمل ولايزال الشغل غير كامل وغير مرتب ولم يضع في جهد كبير ارجو العمل الجاد على التفصيل بعناصر الورشة وعمل تفصيل لكل خطوه بالاضافه الى التفكير العميق بخطوات عمل الورشة ومن ثم وضعها على جدول زمني على المايكورسوفت بروجكت\nعلماً بانني ويوسفنى ان اقول هذا الشي ولكن عدم جديتك بالعمل اجبرت ادارة المشروع على التعامل بهذه الطريقه لذلك اذا لم يتم انجاز العمل بالجوده المطلوبة والوقت المطلوب وهو يوم السبت القادم10/10 سوف يتم خصم خمس ايام من مكافئتك وخمس درجات من مجموعك بالتقييم\n\nهذا واتمنى العمل الجاد\nوتقبل التحية\n\nوربي أنواع ألوان الطيف كلها جتني من قريت الرسالة,شيبو ذولا الشغلة إذلال يعني ولا كيف؟؟؟…جاني تفكير أخرب أم الدنيا وإحتمال أدخل قضية إعتداء بالضرب عليه ,خلاص قفلت عندي,يعني شقول لكم,اللي معي من البترول ميكانيكل كمان,وربي يخلوه يسوي كروكي من المطار لمحل الشغل إذا بيجيهم ضيف من الشرقية أو من حيالله محل,يسوي تصحيح إملائي لشغلات,تصميم كروت ,بزنز كارد,وماخفي كان أعظم…\n\nشغلة ورشة العمل اللي سويته زي ماطلبه بشكل عام يعني لسه ماتحدد أي شي وسويته له بالماكيروسوفت بروجيكت ويرجع يطلبه ثانية:\n\n1) تحديد عنوان وموضوع ورشة العمل.\n2) إعداد أجندة الورشة.\n3) إعداد قائمة بالجهات و باسماء الأعضاء وتحديد نوعية مشاركتهم كحضور أو كمتحدثين.\n4) تنسيق كل مشاركة لكل متحدث من حيث التنظيم والوقت.\n5) إعداد بروشورات للحضور.\n6) توزيع إستمارات للإستبيان لجميع المشاركين والحضور.\n7) Key Person - تحديد الشخص المسؤول عن إدارة الورشة.\n8) إيجاد مكان مناسب لإنعقاد ورشة العمل بأخذ إعتبار الموقع الجغرافي وملائمته لإستيعاب الحضور وعددهم وأهميتهم.\n9) حجز المكان وتهيئته.\n10) تحديد رسوم مالية للإشتراك إن أمكن.\n11) إيجاد الطريقة الأنسب للإعلان بإختيار الوسيلة المناسبة.\n12) إنعقاد الورشة.\n13) جمع وتحليل إستمارات الإستبيان من الحضور.\n14) إستخلاص نتائج الإستبيان ومدى ملائمتها لأهداف إنعقاد الورشة المرجوة.\n15) النتائج والتوصيات.\n\n=-=-=\n\nمثل ماتلاحظوا يبغى شي عام بدون تحديد لا اسم ولا مواضيع ولا أي حاجة يعني كذه خطوات إنعقاد ورشة عمل,طيب أنا اللي طلع مني هذا وش أقدر أسوي بالله عليك بشي أنا ماجيت أطبق عندك علشانه,وشوفوا كيف بالرسالة شيقول فوق.\n\n=-=-=\n\nشباب وش نصيحتكم لي الله يرضى عليكم,منتظر مساعدة للي يعرف بورش العمل وهم مساعدة وش أسوي مع هالمخلوق لأني وربي ناوي شر بس مركد حالي قلت أستشير أخواني بالأول هنا ,لأني بالنهاية لو قومتها خناقة هو مو خسران حاجة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/40721/1", "user": "RedeemeR", "ts": 1096808551000, "tid": 40721, "pn": 1}}', 1096808551000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p529904-me398', 'stk-guest', 'ME 398', 'info', '{"desc": "هادا الإيميل اللي وصلني على إيميل الجامعة من شركة GE\n\nInternship &Coop:\nAn internship or co-op at GE gives a student hands-on experience,\nworking on challenging projects with some of the best minds in business. This is a superb opportunity to give his career a head start while making valuable Contacts. The Coop work experience is a vitally important tool for helping a student determines the course of his career, giving him valuable insight into the workplace, useful experience, and helpful contacts for the future.\n\nIf your Major is: Electric Engineering, Mechanical Engineering, Industrial Engineering, or Finance, Send your email to:\n\nthamer.al\\-fakeeh@ge.com\n\nGE invests over $1 billion in training & development. You’ll never stop learning and growing, because GE is a culture committed to education. We’re NOT training Employees; we’re DEVELOPING talent", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-me-ise-ge/82698/1", "user": "Guest", "ts": 1264591889000, "tid": 82698, "pn": 1}}', 1264591889000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p416777-me398', 'stk-patriot', 'ME 398', 'info', '{"desc": "طلاب الميكانيكال ياخدو الكوأب في شركات كثيرة منها أرامكو و سابك و شركة الكهربا و GE و الخطوط و JGC اليابانية في اليابان و الفلبين.\nأما بالنسبة لقريدات الEvaluation حقت الشركة فهي أفضل في الشركات السعودية كأرامكو و سابك و الخطوط. أما بالنسبة للشباب اللي راحو شركة زي JGC في اليابان فكانت شديدة عليهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/74280/3", "user": "patriot", "ts": 1245506053000, "tid": 74280, "pn": 3}}', 1245506053000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1402818-me398', 'stk-user2352', 'ME 398', 'info', '{"desc": "لطلاب هندسة النظم الصناعية ، كل ما تحتاجه لتسجيل الـcoop وأفضل الشركات\n\nالسلام عليكم\nحياكم الله أخواني طلاب الهندسة الصناعية ،،\nيسرني في هذا الموضوع أن أكتب لكم جميع الخطوات والمعلومات المهمة قبل وبعد تسجيل التدريب التعاوني\nISE350+351 COOP صيف +ترم أول\nISE351+352 COOP ترم ثاني + صيفي\n\nوطالب الكوأب يطبق فترة سبعة أشهر صيفي مع ترم كامل في شركة يكسب من خلالها خبرة عملية ،،\n\nطبعا تختلف الفائدة من شركة لأخرى حسب الشركة فمثلا في سابك وأرامكو تعتبر أقل فائدة من جنرال ألكترك ويونيلفر ،،\nوينصح بالتطبيق بشكل عام في شركة انتاج صناعية مثل شركة يونيليفر أو بروكتر& قامبل P&Gأو جنرال إليكتريك ge أو pwc أو الشركات الجديدة مثل شركة صناعة الورق NAPCO ،،\n\nوفي نهاية الكوأب فيه قريد لـ9 ساعات عوضا عن ثلاث مواد ، تقدر ترفع بها معدلك إذا ابدعت في الشركة بعمل بروجكتات محترمة وكيس ستدي وكتبت ريبورت كامل وسويت برزنتيشن ناجح ،،\nالكورسات المفيدة والمطلوبة من كلام خريجي التخصص قبل الكوأب\n422+ISE303+320+323+325+307+391+390+402+405\nوME322\\323\nوأنصح دائما بأخذ الكورس Mgt-210 قبل الكوأب كمادة اختيارية على طول بعد ما تخلص الكورس Engl-214 لأنه مفيد في تطوير مهارات الإتصال في مجال الأعمال في الشركات\nويستحسن أيضا تدرس كورس اختياري من التخصص قبل الـcoop مثل 470 أو 420 تفيد في بروجيكتات الشركات ، وأيضا يستحسن إنهاء فوق 105 ساعة قبل تسجيل الـcoop حتى يتبقى ساعات قليلة في آخر سمستر\n\nودائما ينصح بالكوأب لمن لا يهمه التأخر سمستر زيادة ويبحث عن اثبات وجوده في شركة معينة يطمح بالالتحاق بها فيما بعد ، وهكذا\n\nالخطوات بالتفصيل :_\n1- تروح الكورديناتور حق الكوأب وتاخد الابلكيشن منو وتوقعو من الادفايزر اللي انتاا راح تختاره … طبعا عشان تلحق من الافضل انك تختار الادفايزر من الاسبوع الأول أو الثاني أو قبلو من الترم يعني لو فكرت الان احتمال كبير ما تحصل الادفايزر اللي انتاا تبغاه …\n\n2- تروح للادفايزر توقع الورقة منو مثل د. هارون بيرم أو نبيل نحاس أو أي دكتور آخر تعرفه …\n\n3- تسلم الورقة للكورديناتور د.سمير العامر حاليا وتأخذ منه خطاب الترشح للكوأب بعد توقيعه وختمه من التشيرمان في القسم …\n\n4- تأخذ نسخة خطاب تعريف وترشيح من ادارة التدريب مع نموذج فرصة تدريب تعاوني COOP\nاختيار الشركة … فيه طريقتين … يا إنك تجيب موافقة الشركة بنفسك عن طريق يوم المهنة أو أي طريقة أخرى … أو إنه تكون عن طريق مكتب التدريب التعاوني في مبني 68 حاليا ادارة التدريب … ولا تنسى اعداد سيرتك الذاتية CV التي بموجبها مع ورقة الترشيح راح تحصل فرصة تدريبية.\nعبر هذا الموقع تقدر تشوف الفرص المعروضة من ادارة التدريب\nhttp://www2.kfupm.edu.sa/stutraining/\n\n5- بعد ما تتأكد إنه الشركة أرسلت أوراقك للجامعة إنه تاخد الكوأب عندهم … بعد الفاينلات تمرهم في مبني 68 الدور التاني مكتب 108 عند تركي الدوسري حالياً وتاخد ظرف مغلق يحتوي على خطاب التوجيه عشان تسلمه الشركة اول ما تداوم وتكمل تعبئة باقي الأوراق والنماذج مثل دليل الإتصال …\n\n6- خلال فترة الكوأب احرص إنو تكون متواصل مع الادفايزر حقك , وبعضهم يطلب يشوفك … فممكن تطلب من الشركة اجازة عشان تجي الجامعة … وطبعا لاتنسى الاشياء المطلوبة منك واللي راح يشروحها لكم في محاضرة عن الكوأب قبل ما تطلعو مثلا زي (التقييم ، الخطة، الخ …) وكمان مطلوب منك ثلاثة progress reports خلال فترة الكوأب السبعة أشهر\n\n7- بعد ما تخلص من الكوأب (طبعا حاول إنك ما ترجع الجامعة إلا وإنت مخلص الريبورت عشان تسلمه للادفايزر على طول لانه غالبا حيمرمطك عدل وبدل …\n\n8- بعد ما يعطيك الادفايزر الموافقة على الريبورت ok… تروح تختار الكوميتي دكتورين والادفايزر حقك عشان تسوي البرزتيشن … وتحجز لك كلاس عبر موقع المسجل\nأو تدور لك كلاس أو لاب فاضي في مبنى 22\nوتاخذ لك 3 نسخ من coop Exam Evaluation من سكرتير القسم\n\n9- اول ما ترجع حاول انك تتأكد انه التقييم وصل لتركي الدوسري ( طيب الذكر) … لانه غالبا يسوي فيها ساندويشات ويضيعها ويطلب منك انو يرسلوها اكتر من مرة . 😆\n\n10- لا تنسى تنسق مع الكورديناتور لانه لازم تسلم له نسخة من الكوأب ريبورت … شوف كيف يبغاه … غالبا نسخة PDF في CD مع نسخة مطبوعة ومغلفة\n\n11- بعدها خلاص … كل سنة وانتا طيب …\n\nملاحظة : جميع أوراق COOP تحصلها مطبوعة ومجهزة على طاولة على يسارك أول ما تخش مكتب قسم هندسة النظم ،،\n\nفي المرفقات راح تجد عناوين أغلب الشركات اللي ممكن تحصل فيها فرصة COOP\nISE 351,352 COOP\nبالتوفيق للجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/165847/1", "user": "user2352", "ts": 1411518540000, "tid": 165847, "pn": 1}}', 1411518540000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p68241-me398', 'stk-user165', 'ME 398', 'info', '{"desc": "بصراحه مو عارف الاسباب , كاتبين فقط اعلان انه سوف يغلق\n\nيمكن قلت المكاتب والكوبي سنتر ماخذ مساحه كبيره من مبنى الاداره , والله اعلم\n\nبس اللي قاهرني ان الموضفين رفضوا يعطوني كل ما يختص بال ME من اوراق وخلافه\n\nوسألتهم وش بتسوون في الاوراق قالوا ما ندري\n\nطيب عطوني انا اعرف اتصرف فيها 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/44478/10", "user": "user165", "ts": 1107777338000, "tid": 44478, "pn": 10}}', 1107777338000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p68739-me398', 'stk-thecollector', 'ME 398', 'info', '{"desc": "أمل\n\nكاتب الرسالة الأصلية الرفيع\nبصراحه مو عارف الاسباب , كاتبين فقط اعلان انه سوف يغلق\n\nيمكن قلت المكاتب والكوبي سنتر ماخذ مساحه كبيره من مبنى الاداره , والله اعلم\n\nبس اللي قاهرني ان الموضفين رفضوا يعطوني كل ما يختص بال ME من اوراق وخلافه\n\nوسألتهم وش بتسوون في الاوراق قالوا ما ندري\n\nطيب عطوني انا اعرف اتصرف فيها 🙂\n\nممكن الجامعة تحب تحول كل المواد (سوفت كوبي) وتحطها على الدوت أورق، أو موقع رسمي شبيه بالدوت أورق؟\n\nيارب…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/44478/17", "user": "TheCollector", "ts": 1108414219000, "tid": 44478, "pn": 17}}', 1108414219000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527015-me398', 'stk-ahm2d1', 'ME 398', 'info', '{"desc": "انا عندي كوأب وتخصصي ميكانيكل, وجاني قبول في شركة Tenaris وسويت المقابله وبعدها ارسلو لي وقالوا فيه Assessment day وبيكون فيه : case studies, discussions, and group activities. فاللي سوا عندهم الاسيسمنت ذا او يعرف اي شيء ممكن يفيدني عنه اكون شاكر له.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tenaris/183458/1", "user": "Ahm2d1", "ts": 1607441759000, "tid": 183458, "pn": 1}}', 1607441759000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198875-me398', 'stk-naheeb', 'ME 398', 'info', '{"desc": "شكراً جزيلا أخوي العزيز…\nأنا رحت اليوم وكلمته …بخصوص الفرص المتوفرة عندهم حاليًا للميكانيكال قال لي فيه 2 ولكنها للساينس…\n\nأما بخصوص الطريقة الثانية …فقال نفس الكلام اللي قلته لكن ما استفدت كثير يمكن لأن الدكتور كان مستعجل شوي…\n\nبس المشكلة كيف أتواصل مع الشركة …وأنا بصراحة ما عندي خيار محدد أقصد ماعندي شركة محددة …بس ماعندي مشكلة بين اليابان وكوريا الجنوبية…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/141834/9", "user": "naheeb", "ts": 1363116942000, "tid": 141834, "pn": 9}}', 1363116942000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p989762-me398', 'stk-blue_light', 'ME 398', 'info', '{"desc": "لما تخلص البرزنتيشن يجيك كم دكتور ينقز ويستفحل قداامك…فخلك طبيعي…حاول تجاوب باللي تقدر المهم لاتسكت…صرف جاوب اجابة ثانية…المهم لاتسكت…فيه اسىلة سالوني مااعرف اجابتها…بس خشيت في عيونهم وجاوبت واصريت على اجابتي…\n\nالحاصل في الموضوع :الله يوفقكم…هم وبينزاح منكم زي ماانزاح مني…لكم خالص تحياتي ودعواتي لكم بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/121332/5", "user": "blue_light", "ts": 1329725473000, "tid": 121332, "pn": 5}}', 1329725473000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1469494-me398', 'stk-hussain_ali93', 'ME 398', 'info', '{"desc": "السلام عليكم/\nتدربت COOP عند شركة ROSEN في السمستر 153-161، تخصصي CISE وكانو يعطو مكافأة 3500 ريال شهرياً للمتدرب، تم التقديم عن طريق يوم التدريب في الجامعة.\n\nالشركة في وادي الظهران يعني كانت قريبة من الجامعة، كان المفترض أتدرب في مركز الأبحاث لكن شائت الظروف اني أكمل تدريبي في قسم الصيانة، بشكل رئيسي كان الشغل تبديل قطع وصيانة للـIn-Line-Inspection Tools ، الموظفين كانو جداً مستاعدين لكن كطالب CISE أعتقد إني ماتلقيت تدريب مناسب + راح تشتغل معاهم تقني. هم في العادة ياخذو طلاب الميكانيكا وأنا كنت أول طالب CISE عندهم.\n\nأثناء فترة التدريب قدرت أتعلم الحساسات اللي يستخدموها والأجزاء الإليكترونية داخل الأدوات، إذا كنت من طلاب الميكانيكا أعتقد إن التدريب عندهم راح يكون مناسب.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/59", "user": "Hussain_Ali93", "ts": 1488804877000, "tid": 170460, "pn": 59}}', 1488804877000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1478030-me398', 'stk-k_94', 'ME 398', 'info', '{"desc": "نوع التدريب ( Coop )\n\nاسم الشركة : شلمبرجير\n\nالسنة : 2017 ( 162+163)\n\nالتخصص + الجامعة: CHE ; KFUPM\n\nمكان التدريب + القسم : القسم Drilling and measurement , بالنسبة لمكان التدريب اماكن مختلفه يعتمد على موقع الحفر ( تناجيب , الخرسانية , العثمانية , ابو جفان , المزاليج , خريص , الخ … )\n\nالمكافأة : 1500 ريال\n\nطريقة التقديم : يوم التدريب بالجامعة\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) : الشركة حلوة للي يعطيها لكن شخصيا ما ناسبتني , دوام 7 ايام بالاسبوع 12 ساعه باليوم والاجازات بالقطاره لانك طالب كواب , لكن ما قصر مديري جمع اجازاتي واعطاني اياها اخر التدريب 🤠 , لكن كل التعب والقروشة ذي ما تسوى ال1500 وطبعا القسم ما فيه شي كمكل ولا اعتقد اي تخصص ندرسه بالجامعه مشابه له ( ممكن حقين الكهرب في لهم signal والميكانيكل ممكن يدبرون لهم شي بالادوات ) اصلا مسماك Field engineer يعني يعتبر شي مغاير تماما للجامعه وللامانه الشغله ما يبي لها هندسة ولا شي , حتى الشباب من كلية الجبيل وينبع الصناعية يسوون نفس الشغل الفرق بينكم يكون في المسمى الوظيفي فقط .\n\nالشركة تضغط عليك بالتدريب ( يعتمد عالقسم طبعا ) ولكن ذا الشي يخليك تتعلم بسرعه , المشكلة الوحيده انها مو بتخصصك يعني ممكن تاكلها بالفاينل ريبورت X_X , شخصيا جتني شركتين غيرها في قلب تخصصي ولكن فضلت اختار شلمبرجير عشان اشوف تناسبني اختارها بعد التخرج او لا ولله الحمد 7 شهور افادتني كثييير عن الشركة والمستقبل الوظيفي ونظام الترقيات والكورسات حقت التطوير وشخصيا اشوف اي طالب يطبق بشركة حاول تحتك بالموظفين كثير عشان تعرف عن الشركة اكثر لانه مستحيل كل المعلومات تلاقيها بالنت , لازم تسمع من ناس لهم سنتين او ثلاث بالشركة …\n\nالصراحه ماني من الناس اللي اعرف اشرح تجربتي بالشكل المناسب لكن اللي عنده اسئلة مستعد اجاوبها سواء عن التدريب او القسم بشكل عام 🙄", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/64", "user": "K_94", "ts": 1501843965000, "tid": 170460, "pn": 64}}', 1501843965000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486796-me398', 'stk-fahad_al-khaldi', 'ME 398', 'info', '{"desc": "نوع التدريب ( COOP )\nاسم الشركة أو جهة التدريب : Aramco\nالسنة : 2nd Half of 2017\nالتخصص + الجامعة: Jubail University College - ME\nمكان التدريب + القسم : الخرسانية - PMT\nالمكافأة : 4500 ريال\nطريقة التقديم : موقع الشركة\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) :\n\nللامانة كثير من الاصدقاء أخذوا تدريبهم في أرامكو و90% منهم تجربته ما كانت مرضية وأنا كذلك ،\nوالسبب الاول طبعا يعتمد على القسم اللي أنت فيه وعدم وجود خطة واضحة يقدر الطالب يمشي عليها ويعرف إلى أين هو متجه.\n\nطبعًا بالنسبة لي كانت فترة تدريبي (صيف + سمستر أول) وكنت مع الـ Project Management Team وكان شغلهم بشكل عام facilities projects واغلبها well tie-in projects لـ الخرسانية بلانت وكانوا على الـ كونستراكشن بس يعني مشاريع صغيرة ، كان مافي اهتمام ابدا جيت او ما جيت تعلمت او ما تعلمت وكانت اغلب مشاريعهم متاخرة ويبغون يلحقوا يقفلوها فـ محد كان يلتفت لك ، داومت اول اسبوع وتعرفت على القسم والاسبوع الثاني قالوا خلك مع هالشخص طبعا هو مهندس هندي حبيب وخلوق وفاهم وتعلمت منه كثير أشياء بس ما يعطيك شغل بس يشرح لك واطلع معه السايت شبه يومي وبعد فترة طلع اجازة وضعت انا بعده هههههههههه ، يعني لو ما كان موجود هالشخص كان توهقت فـ الريبورت ولا عرفت وش أكتب فيه ، والشباب الباقيين لما خلصت الكواب في اخر اسبوع يقولوا ما كان ودنا نتعبك معنا وحن فالعادة طلاب الكواب نخليهم على راحتهم ولا نعطيهم شغل ، عالعموم القسم اللي كنت فيه ما حبيته مره والسبب أن أغلب المشاريع تتكرر كل مره مع بعض التغييرات في الديزاين و الكونستركشن كومبنيز محدودة على شركتين بس بعكس الميقا بروجيكتس.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/71", "user": "Fahad_Al-khaldi", "ts": 1517002845000, "tid": 170460, "pn": 71}}', 1517002845000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1511896-me398', 'stk-homoud295', 'ME 398', 'info', '{"desc": "اسم الشركة أو جهة التدريب: ارامكو السعودية\nنوع التدريب : COOP\nالسنة : 2019\nالتخصص + الجامعة:\nME - Jubail University College\nمكان التدريب + القسم :\nمصفاة راس تنورة - صيانة معامل التكرير الشمالية\nالمكافأة : 4500 ريال\nطريقة التقديم : الموقع الرسمي\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) :\n\nبسم الله الرحمن الرحيم ، أتمنى تفيدكم تجربتي للتدريب التعاوني مع شركة أرامكو السعودية.\n\nبفصّل الموضوع على شكل اسئلة واجوبة:\n\n١- هل يوجد خطة للمتدرب ، وهل طبقتها ؟\n\nنعم ، يوجد خطة بمسمى (Individual Development Plan) أو IDP يعطونها للمتدرب وللموظف الجديد فيها نقاط بالمسؤوليات والمهام الخاصة ، والحمدلله قدرت اطبقها بكل يسر بالتعاون مع الرئيس المباشر. وهنا اذكر المسؤوليات بالخطة للفائدة:\n\n• Understand the maintenance planning & scheduling process.\n\n• Gain basic understanding of compnay contracting procedure.\n\n• Work with mechanical unit for hands on experience on rotating/static equipment.\n\n• Work with electrical and instrumentation unit for hands on experience.\n\n• Worked with plnt maintenance engineer for exposure to company international standards as well as engineering drawings.\n\n• Work with maintenance engineer to gain the understanding of work order planning, material ordering and execution.\n\n٢- أهم المهارات المكتسبة؟\n\n- حضور الاجتماعات والمشاركة فيها من أهم الامور اللي حبيت ان اطور نفسي فيها ، فكنت احضر اجتماعين على الاقل باليوم بالبلانت وبالقسم والمشاركة في التحديات اللي تواجهنا كل يوم.\n\n- مهارات التواصل بشكل عام والاندماج في بيئة العمل يجعل منك شخص ناجح بكل المقاييس.\n\n- الأمن والسلامة وهنا فعلاً اقدر اقول ان أرامكو تشكر على جهودها في هذا المجال ، و غيرت فيني الشي الكثير سواء داخل العمل او حتى على اسلوب قيادتي للسيارة.\n\n- التعرف على العالم الهندسي الواقعي ، كلنا ملينا من قراءة الكتب والسلايدات لكن لما تنزل المصنع او البلانت وتشوف بعينك اللي درسته وتكون قادر على الربط مابين النظريات والشيء الواقعي فعلا شي يخليك ماتندم لحظة وحدة على دراستك.\n\n- الكورساااات تبع ارامكو Elearning ، اخذت مايقارب ٢٠ كورس مختلفة مابين السلامة واخلاقيات المهنة والهندسة ومعامل التكرير و الكثير. للأمانة انصح كل متدرب بأرامكو يستفيد من هذا الشي الجميل صراحة.\n\n٣- كيف كانت بيئة العمل ؟\n\n- اجابة صادقة ، بيئة ودودة جدا وواجهت ناس كثير تحب الخير ومساعدة الطلاب المتدربين والاهم من ذا ان الموظفين يحبون اللي جالسين يسوونه.\n\n٤- وش التحديات اللي واجهتها ؟\n\n- السوبرفايزر وكلني مهمة وهي اني كمهندس صيانة مثل الزملاء الموظفين اغطي معملين تكرير من اكبر المعامل بالمصفاة الشمالية والمسؤولة عن انتاج البنزين ٩١ و ٩٥ ، طبعا المهمة لمدة اسبوع وكنت احضر الاجتماعات يوميا بالمعامل مع الاوبريشن واسجل اعمال الصيانة المطلوبة وايضا نناقش المشاكل المتواجدة وكيفية حلها وطبعا زيارة اعمال الصيانة بالمعمل يوميا والتأكد من انجازها بالشكل المطلوب.\n\n- تم تعييني في اخر شهر بالتدريب في اعمال شت داون لبلانت معين ، طبعا مسماها (Turnaround & Inspection) او T&I Activities ، وهي ايقاف تشغيل المعمل بشكل جزئي او كلياً لإتمام اعمال الصيانة للمعدات المهمة مثلا الهيت اكسشينجر … الرياكتر … البويلر والفرنس … البمب والكمبرسر وغيرها الكثير. تجربة كانت فريدة من نوعها وهي الاهم للمهندس الميكانيكي بالذات لانك تشوف جميع المعدات والآلات مفتوحة ويتم صيانتها وهنا تكمن الفائدة انك تعرف القطع الداخلية والخارجية.\n\n٥- كمهندس ميكانيكي وش الكورسات اللي استفدت منها؟\n\n- اكثر مادة استفدت منها شخصيا هي مادة الكتڤ Maintenance Engineering … فعلا كل شي درسته شفته وطبقته وانصح اي مهندس ميكانيكي ياخذ المادة ضرورية جدا ، اغلب المهندسين الميكانيكيين هناك بمسمى maintenance engineer.\n\n- Heat Transfer ( عشان الهيت اكسشينجر اكثر شي ).\n\n- Fluid Mechanics (pumps, compressors, turbines, pipes)\n\n٦- كيف كانت تجربتك؟ (عطنا الزبدة)\n\nولله الحمد اولاً واخراً التجربة كانت ممتازة جدا والتوفيق من الله سبحانه ، واتمنى لكم التوفيق جميعاً لازم تعرفون ارامكو بحر بأقسامها وتخصصاتها لكن الكلام اللي ملحه فيه ان مصفاة راس تنورة يسمونها مدرسة ارامكو ، لان اولا اكبر مصفاة بالشرق الاوسط قبل جيزان حالياً وفيها اكثر من معمل تكرير وبالتالي المهندسين بيستفيدون جدا من اللي بيشوفونه ويتعلمونه ، ثانياً اغلبهم خبرات تفوق ال٢٠ سنه يعني ماشاء الله كيف ماتبي تستفيد.\n\nهذا اللي كان عندي واتمنى تعذروني طولت بالموضوع لكن حبيت افيد الكل باللي اقدر واشارك تجربتي ، واللي عنده سؤال انا حاضر … دعواتكم واتمنى لكم التوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/81", "user": "homoud295", "ts": 1562107377000, "tid": 170460, "pn": 81}}', 1562107377000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1196970-me398', 'stk-majdi90', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله\nأخباركم طيبين ان شاء الله\n\nيا أخوان أنا مقبل على تدريب تعاوني (Coop - Training) في الصيف القادم … وودي التدريب يكون في شركة مرافق (ينبع) … فـ قبل ما أروح ينبع لشركتهم ودي أعرف كيف اجراءاتهم في الحصول على فرصة للتدريب عندهم لأن موقعهم مافيه ايميل نراسلهم واتصلت على الرقم اللي في الموقع ومحد رد …\n\nعلما ان تخصصي هندسة ميكانيكية - جامعة حائل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/141716/1", "user": "Majdi90", "ts": 1362763499000, "tid": 141716, "pn": 1}}', 1362763499000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467529-me398', 'stk-tomoo', 'ME 398', 'info', '{"desc": "سلام عليكم\nياشباب انا ساينس وابحول ابلايد ولازم انزل me 414 الترم الجاي علشان اطبق 163+171\nالسوال حاولت انزل الماده من البورتال ماقدرت يقول انها خارج تخصصك فما ادري اش اسوي هل اروح للتشيرمان او اغير تخصصي اول شي بعدين انزلها لاني اخاف اتاخر واخر يوم للااصافة الاربعاء\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-414/175915/1", "user": "TOMOO", "ts": 1486140651000, "tid": 175915, "pn": 1}}', 1486140651000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1361898-me398', 'stk-stu-kfupm', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nياشباب انا تفاجأت اليوم برسالة من ارامكو مضمونها التالي انه شركة ارامكو تطلبني للـسمر بروقرام لكن الغريب اني انا ماقدمت على ادارة التدريب اني ابغى فرصة تدريب ولا سوويت اجراءات التدريب التعاوني لانه باقيلي شي في خطة الميكانيكال وانا كوواب بالاصل لكن قدمت على هذا البرنامج لانه افكر فرصة برنامج صيفي لكافة الطلاب وش مايكون من سمر والا كوواب\nفمااعرف وش السواة والله الفرصة حلوة وانا كوااب … ؟\n\nاتمنى الرد بالجواب الكافي … جزاكم الله الف خير … ❤️ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-program-aramco/160824/1", "user": "stu-kfupm", "ts": 1399386697000, "tid": 160824, "pn": 1}}', 1399386697000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1204208-me398', 'stk-nayef', 'ME 398', 'info', '{"desc": "تعلن شركة تيناريس عن توفر فرص لبرنامج التدريب التعاوني (COOP) والمقرر بدءه خلال يونيو من العام 2013 لمدة 28 أسبوعاً\n\nحيث تقدم الشركة للمتقدمين السعوديين لهذا البرنامج فرصة الإحتكاك بأصحاب الخبرة في مجالها و التدريب المناسب في بيئة عمل مثالية يكون الإحتكاك فيها بموظفين ومدراء من جنسيات مختلفة حول العالم مما يضمن اكتساب الخبرة بالإضافة الى العوائد المادية المنافسة\n\nالتخصصات المطلوبة:\nالهندسة الميكانيكية\nالهندسة الكهربائية\nالهندسة الصناعية\nالهندسة الكيميائية\n\nالرجاء إرسال السيرة الذاتية إلى البريد الإلكتروني المذكور أدناه خلال مدة لا تتجاوز April 12,2013\n\nPlease submit your CVs to:\nmshakeel@tenaris.com\n\nلمعلومات حول الشركة:\nwww.tenaris.com\n038127701", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-tenaris/142533/1", "user": "NaYeF", "ts": 1364822649000, "tid": 142533, "pn": 1}}', 1364822649000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p24829-me398', 'stk-heat', 'ME 398', 'info', '{"desc": "حرام ياشباب الظلم\n\nربما يكون الدكتور سعيد سيد شديد في تعامله وجلف بعض الشئ …|1|\nلكن الدكتور سعيد من افضل ان لم يكن الأفضل في قسم الهندسه الميكانيكيه… والكل يعرف هذا الشئ …:)🙂\nوشدته تأتي من حرصه على ان يتم العمل بالطريقه الممتازه وان يفهم الطالب ماهو معنى العمل الحقيقي …( وخلوا عنكم يتراه يعطي قريدات بالهبل)…:D|3||3||3||10|", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-coordinator/22489/4", "user": "heat", "ts": 1055815383000, "tid": 22489, "pn": 4}}', 1055815383000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1056564-me398', 'stk-user2781', 'ME 398', 'info', '{"desc": "هلا بك اخوي\n\nانا طبقت كوآب في احد شركات سابك 🙂\n\n\\\n\nالتطوير والدورات كلها تعتمد ع مديرك بالادارة\nبس اخبر شركة كيميا كريمه مع موظفيها بما ان شركهم امريكي 🌹\n\n(الي يقدر يجاوب هذا السؤال هم موظفوا كيميا )\n\n\\\n\nإذا اشتغلت مهندس كهربائي في ادارة الصيانه او الاعتماديه (reliability )\nبتكون ممتاز في الـ distribution والبروتيكشن والماشين\nوطبعاً بتفهم ال sub station\n\nوبكذا تقدر تروح اي شركه ثانيه نفس البيزنيس\nمثل ارامكو او شيفرون او what ever\n\n\\\n\nنظام تمليك المنازل يعتمد ع قريدك وخدمتك وعلى عدد عيالك وزحمه 🤠\nبس انت كمهندس تبدأ بقريد 10 ما شاء الله، ما اتوقع تتاخر\n\n\\\n\nايه اكيد الباب مفتوح للكهربائي والميكانيكي\nوانت كثر ما تطلع فوق لازم تقوي نفسك بالـ management skills\nيوم كنت اطبق قريت الـ job description حق الـ superintended لقسمنا\nوكان من المطلوب انه يفضل انه يكون كهربائي او ميكانيكي …\n\n\\\n\nعفواً عزيزي\nومعليش ما قدرت اجاوبك لاني كنت كواب 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/127455/7", "user": "user2781", "ts": 1339927418000, "tid": 127455, "pn": 7}}', 1339927418000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316571-me398', 'stk-shubailiferas', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nمن خلال فترة تقديمي على الشركات لاحظت انه بعضها يكرر أسئلة المقابلة الشخصية … من أبرز الشركات اللي سويت معها المقابلة سابك و ارامكو و معادن … زبدة الموضوع عشان ما أطول عليكم … أبحط أسئلة مقابلتي مع كل شركة وبالتوفيق للجميع\nأنا من دفعة 2008 خريج 2013 والجي بي اي فوق 2.5 والتخصص هندسة ميكانيكية تطبيقية\nCOOP at Sabic - Kemya\nSabic – purchasing Department\n\nTalk about yourself?\nIf I meet you someday in the street and we talked then you introduced yourself as a mechanical engineer and I didn’t understand what do you mean by that, can you explain to me what mechanical engineering is?\nIf you have two job offers, the first from Sabic in Jubail and the second from Aramco in Dhahran where you and your family lives, where you will go and why?!\nDid you study ISE 307 (Economics for engineers) at the university? What did you gain from this subject and what the subject talks about in general?\nAre you willing to work in office? Are you willing to work in an environment that does not allow you to go to the field?\nWhat did you do in your COOP training?\n9*7=?\n8*5=?\nDo you want to study master degree? ( I said yes) then he asked how are you going to do so? What do you want to study?\nDo you have any question for us?\nSabic – Kemya\n\nWhen you are planning to get married? (I think the interviewer asked this question to break the ICE)\nTalk about yourself?\nDid you study Thermodynamics in the university? Talk about what do you know in thermodynamic?\nDid you study heat transfer in the university?\nWhat are the differences between thermodynamic and heat transfer?\nDid you take Turbo machinery in the university? (I said No) Then he asked did you work in your COOP with steams turbines? (I said Yes) Then he asked can you explain to me the thermodynamic part and the heat transfer part which are related to the steam turbines?\nCan you draw Rankin cycle? Is it real? Explain it?\nCan you explain Carnot cycle?\nDid you study HVAC in the university? (I said No) then he asked what did you study elective in the university? (Pumping Machinery)\nWhat did you study in pumping?\nHow can you select a pump? What is the equation of specific speed?\nWhat is corrosion? What is NPSHA&NPSHR? Can draw the curves witch related to cavitation on the board? ( I draw Q&H graph with NPSHA&NPSHR once and another time with H&Q& efficiency finally I draw the Liquid, solid and vapor phase diagram)\nWhat is cavitation? Can you define it?\nWhy you want to leave Aramco?\nYou took a course about wielding? Can you define wielding?\nYou’ve done your COOP training in Kemya last year right? What will be your responsibilities as an engineer?\nWhat is root cause? How you can find the root cause of an issue? If you manage to find it what you will do with it?\nWhat do you know about the LDPE plant in Kemya?\nDo you have any question for us?\nAramco\n\nTalk about yourself?\nWhere did you do your COOP training? Talk about the process of Kemya?\nTalk in general about your COOP in Kemya?\nWhat is your senior project? Can you talk about it?\nDo you have any question?\nMa’aden\n\nTalk about yourself out of your C.V?\nWhat do you think about KFUPM? If you go back to high school are you going to joint KFUPM?\nWhy your GPA below 3? Is it because of the faculty of the university? (I said it is because of me)\nIf you have offers from Sabic and Ma’aden, where you will go?\nWhat is the last book that you read?\nWhat are your hopes?\nWhy you will leave your current job?\nDo you have any questions?", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155059/1", "user": "ShubailiFeras", "ts": 1389092784000, "tid": 155059, "pn": 1}}', 1389092784000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1417057-me398', 'stk-maslamh', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nيوجد فرص تدريب تعاوني Co-op في تحالف BACS مشروع مترو الرياض لاين 1&2 لتخصصات الهندسة المدنية, الميكانيكية, الكهربائية, المعمارية. شركات التحالف بكتل,المباني, اتحاد المقاولين.\nالعمل مشترك بين جميع الشركات يعني التيم تحصل فيه موظفين من جميع الشركات الثلاث.\n\nالي له رغبه يرسل الCV (يكون المعدل في الCV) على الايميل هذا:\n\namalgaht@bacsrmp.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/167850/1", "user": "Maslamh", "ts": 1417499640000, "tid": 167850, "pn": 1}}', 1417499640000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429953-me398', 'stk-hassan_al_yagoub', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nمعاكم حسن آل يعقوب … احد خريجي برنامج اديسون للتطوير الهندسي لشركة جنرال إلكتريك بقسم الطاقة و الماء “Power &Water”. خلال رحلتي للتقديم على البرنامج في سنة 2011 واجهت صعوبات لمعرفة معلومات عن البرنامج وخاصة باللغة العربية، ولهالسبب حبيت أوضح البرنامج بأكثر قدر من التفاصيل وأجاوب على أسئلتكم بخصوص البرنامج.\n\nفي شركة جنرال الكتريك فيه عدة برامج للتدريب مثل برنامج “OMLP” و\"CLP\" و “ITLP”.\n\nماهو برنامج الاديسون؟\n\nبرنامج الاديسون هو برنامج تقني، مدته سنتين ونص راح تشتغلو فيه 5 وظائف مختلفه كل وظيفه مدتها 6 شهور. الوظايف راح تغطي التصميم، الاختبار، التحليل أو الاستشارات الهندسية المتعلقه بالتوربينات Gas Turbines. خلال فترة عملكم راح تكونو ببرنامج تدريبي نظري مكثف لمدة لمدة 4 سنين “سنة بعد التخرج من البرنامج”. بشرح ليش بعد مااتكلم عن المقابلة.\n\nفترة المقابلة:\n\nالمقابلة بالنسبة لي كانت 4 مقابلات:\n\nأول مقابلة لي كانت للتأكيد على المعلومات في الCV. أسئلة بسيطة، وين إشتغلت، معدلك، سنة التخرج، عن الوظايف الي اشتغلتها “الاديسون يتطلب سنة خبرة وبالنسبة لطلاب البترول ففترة الكوب اب تغطي”.\n\nالمقابلة الثانية كانت تتكلم عن شخصيتي، وعن بعض الامور الي تتكلم عن دوري بالفريق ودوري القيادي.\n\nالمقابلة الثالثة كانت مقابلة تقنية مع مسؤول بامريكا وكانت اصعب مقابلة. بهذي المقابلة، جهز ورقة وقلم وويبكام. راح يسالك عن نفسك، مشروع تخرجك، خبرتك وراح يعرض عليك سؤال يا إما متعلق بمشروع تخرجك أو راح يطلب منك تحل سؤال تقني يقيس عليها مستواك بالهندسة.\n\nالمقابلة الرابعه هي تكون اكثر كشرح لك للوظيفة وانهم يتاكدوا انك فعلا مستعد للتضحيات تسويها \"مثلا بالنسبة لي اضطريت اني ااجل زواجي لبعد التخرج من البرنامج، بسبب ضغط العمل.\n\nاذا عديت كل هالمقابلات… الف مبروك !!\n\nقبل مااشرح كيف نظأم البرنامج، بغيت اوضح انك راح تكون مسجل في برنامجين للتدريب، برنامج الاديسون EEDP وبرنامج ACE\n\nالEEDP او الاديسون هو مثل البرامج التدريبية الثانية راح تشتغل 5 وظايف وراح تاخذ 5 دورات تدريبية مدة كل وحدة منهم اسبوع. مدة البرنامج سنتين ونص.\n\nمتطلبات انك تتخرج من الاديسون:\n-العمل ب5 وظايف مختلفة. وظيفتين بتكون بامريكا و 3 وظايف بالشرق الاوسط.\n-اكمال B course “راح اشرحه بالقسم الثاني”.\n-اكمال كورس الsix sigma.\n-اكمال كورس foundation of leadership. “من اجمل الدورات التدريبية الي حضرتها بحياتي” … هذا شرح للكورس\nGE CLP BLOG - Blog\n-اكمال كورس Eng@ge وهو عبارة عن بطولة للروبوتيكس وبنفس الوقت مجال تتعرف فيها على ناس من برنامج الاديسون من شركات مختلفه من جي اي.\nENG@GE Run 1 Video - YouTube\n-اكمال كورس teardown وهو كورس يختلف من سنة لسنة … وقت ماحضرته كان فيه شرح مفصل عن وظيفة الfield engineer و المشاكل التقنية لمحطة الكهرباء\n-اكمال كورس powerplant fundamentals وهذا الكورس يشرح كل شي متعلق بمحطة الكهرباء وجدا مكثف ومدته اسبوع.\n\nالACE هو التدريب النظري ومدته 4 سنوات. يتضمن انك تدرس 34 نظري في اول سنة، و 15 كورس بالسنة الثانية وتقدم مشروع جماعي ومشروع تخرج شخصي. باختصار انت راح تخلص\n\nمتطلبات انك تتخرج من ACE:\n1- انك تنهي متطلبات A course بالنسبة للسنة الاولى.\nA course هو عبارة عن 34 كورس … راح تدرس فيها تقريبا عن كل شي متعلق بالهندسة الميكانيكية او الكهربائية وراح تاخذ عدة كورسات متعلقة بالرياضيات. هذا الكورس من دون مبالغه ممكن تكون اصعب سنة لك بالشركة وبسبب انك راح تاخذه بامريكا وماراح تكون عندك ارتباطات عائلية راح يكون اسهل. الكورس راح يكون اسبوعي بحيث انك تحضر محاضرة كل ثلاثاء لمدة اربع ساعات. وتشتغل على الواجب كل يوم بعد ساعات الدوام مع الجروب الي تشتغل معاه “بالعادة نطلع من الدوام الساعة 9 الى 11 الليل.” بعدها راح تشتغل على الريبورت بالويكند وراح ياخذ منك من 5 الى 10 ساعات حسب سرعتك وصعوبة المادة. راح يكون فيه اختبار نهائي لكل 17 كورس بحيث ان معدل الدرجات راح تحسب ك3 ساعات لدرجة الماجستير.\n\n2- انك تنهي متطلبات B Course بالنسبة للسنة الثانية.\nB course هو عبارة عن\n\n* 15 كورس … الكورسات اقل نظرية واكثر تطبيقيه من ناحية المعلومات … وراح تاخذ اسبوع منها ككورس تطبيقي بmachine shop. را\n* مشروع تشتغل فيه مع 4-5 اشخاص لمدة 8 شهور وهو بالعادة يكون تصميم لقسم او معدة جديدة.\n*اكمال كورسين على الاقل للماجستير واثنين منهم يكونو متعلقين بموضوع واحد Minor.\n\n3- انك تنهي متطلبات C Course قبل نهاية السنة الرابعه\n*اكمال مشروع تخرج “ACE Project” وهو عبارة عن مشروع او بحث شخصي “على الاقل 90% من المشروع لازم تكون منفذه بنفسك بدون مساعده”. خذ ببالك انك تقدر تختار اي مشروع وتقدر تخلص من مشروع التخرج قبل ماتخلص حتى من الـA Course.\n\n*اكمال درجة الماجستير باحد الجامعتين North Carolina State University أو Georgia Institute of Technology.\n\nراح احاول ان شاء الله اشرح طبيعه الروتيشنز واجيب قد مااقدر من الستفسارات منكم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ges-edison-engineering-development-program/170303/1", "user": "Hassan_Al_Yagoub", "ts": 1444324498000, "tid": 170303, "pn": 1}}', 1444324498000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1386435-me398', 'stk-user7239', 'ME 398', 'info', '{"desc": "انا طالب ميكانيكال كوواب في شركة التصنيع\nلو سمحت ترسلي الخطة work plan\nوتكون المودل الموجود في قسم الميكانكال(4 صفحات)\nلان السوبرفايزر عندي في الشركة ارسلتله المودل قبل اسبوعين وللحين ما خلصه\nالحل يا شباب لا هنتوا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/162560/3", "user": "user7239", "ts": 1405416331000, "tid": 162560, "pn": 3}}', 1405416331000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1254281-me398', 'stk-ibrassa', 'ME 398', 'info', '{"desc": "نصيحة من واقع تجربة\n\nالكواب صحيح بيرفع المعدل وبتاخذ اجازة من الدراسة وتتعود على بيئة العمل اكثر\n\nلكن من وجهة نظري الصيفي افضل… اول شي من ناحية انه شهرين فراح يكون حماسك للشغل اكثر عشان تسوي حاجة مهمة تكتبها بالريبورت قبل لاتخلص… انا خذت كواب ومليت من طول المدة\n\nثاني شي اذا خذت صيفي راح يكون عندك 3 كورسات اليكتف… وهذي مهمة جدا لو تختار كورسات معينة راح تفيدك جدا بالوظيفة … انا ميكانيكال وتخرجت وتوظفت ولله الحمد … من اكثر الاسئلة اللي سالوني شنو الاليكتف اللي خذت… لان احنا بالجامعة ناخذ هندسة ميكانيكية عامة او كيميائية عامة… كورسات الاليكتف هي اللي تخليك تتخصص بحاجة معينة او اكثر بدل ماتكون مهندس كيميا عام…\n\nعالعموم هي برضو عالتجربة ممكن يكون الكواب فعلا افضل لكن تجربتي ماكانت بهالشكل … لكن عن نفسي لو يرجع الوقت ادخل ساينس واخذ كورسات اليكتف ندمان ماخذتها\n\nوبغيت اقول لك لاتفكر بموعد التخرج… ماحد بيهتم انت خذت الجامعة بكم سمستر المهم الناتج … اذا تبغى ترفع معدلك خذ ساعات قليلة وشد حيلك… وبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148048/8", "user": "Ibrassa", "ts": 1377086956000, "tid": 148048, "pn": 8}}', 1377086956000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p698012-me398', 'stk-user1508', 'ME 398', 'info', '{"desc": "انا توي مخلص كواب … و انا ابتكلم عن نظام قسمنا ( الهندسه الكهربائيه ) و ما ادري اذا كانوا الميكانيكال زينا و الا لا :\n\nالبروجريس ريبورت (يجب عليك تسليم 3 بروجريس ريبورتس ) تسلم كل 7 اسابيع نسخه ترسل للكواب ادفايزر و نسخه ترسل للويب سي تي ( و نسخة الويب سي هي اللي عليها قريد و فيها ديد لاين )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/94501/7", "user": "user1508", "ts": 1283857254000, "tid": 94501, "pn": 7}}', 1283857254000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1210809-me398', 'stk-user4636', 'ME 398', 'info', '{"desc": "مو لازم 3 انا 2.5 وانقبلت\n\nالمقابله يسألون اسئله شخصيه بعدين يدخلون شوي اسئله عن التخصص مثلا انا سألوني عن الجازتورباين ايش هو ووو\n\nوسألوني بعد اسئله خرابيط استفزازيه شوي مثل ليش دخلت ميكانيكل واجاوب ويقول طيب ليش مو الكترك!! واجاوب يقول طيب الالكترك اهم من الميكانيكل!!\n\nكذا يطقطق يبي يستفز\n\nالزبده بالاخير سلكت اموري وانقبلت\n\nوسألني بعد قال قدموا علينا ناس كثير ليش نختارك انت!! 😕\n\nوهيك اسئله تقهر بس لازم ترد بذكاء واذا استلكع عليك تستلكع عليه بهداوه\n\nبالنسبه لطبيعة الشغل حسب المكان فيه بالرياض قسم الهيلث كير وفيه عندنا بالدمام الجيمتيك صيانة لروترات تبع التورباينات وللجينيريترات وللنوزلز …الخ\n\nبالنسبة هل جي اي ام سابك مادري صراحه بس للأمانه احس سابك افضل احساس فقط لكن مادري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ge/143105/6", "user": "user4636", "ts": 1366033890000, "tid": 143105, "pn": 6}}', 1366033890000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1478376-me398', 'stk-user5894', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمه الله\n\nهل فيه ملف تجميعي او مراجعه للاسئله في المقابله للمهندس الميكانيكي ( خصوصا في الثيرمو داينمكس و الفلود )\n\nواكون من الشاكرين\n\nمع العلم ان عندي مقابله بعد ١٢ يوم … وهذي الرساله الي وصلتني منهم\nوابي احضر بقدر المستطاع\n\n\"\nfocus on your basics in your major, graduation project and internship or your experiences.\"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/177336/1", "user": "user5894", "ts": 1502368455000, "tid": 177336, "pn": 1}}', 1502368455000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1070395-me398', 'stk-vip_master', 'ME 398', 'info', '{"desc": "Dear Coop Student\n\nThis is to inform you that I am in vacation till 01 September 2012.\nYour coop reports should be sent to your COOP ADVISOR NOT TO ME.\nYour coop reports should be sent to your COOP ADVISOR NOT TO ME.\nYour coop reports should be sent to your COOP ADVISOR NOT TO ME.\nYour coop reports should be sent to your COOP ADVISOR NOT TO ME.\n\nSEND YOUR COOP REPORTS TO YOUR COOP ADVISOR NOT TO ME.\n\nSEND YOUR COOP REPORTS TO YOUR COOP ADVISOR NOT TO ME.\n\nSEND YOUR COOP REPORTS TO YOUR COOP ADVISOR NOT TO ME.\n\nSEND YOUR COOP REPORTS TO YOUR COOP ADVISOR NOT TO ME.\n\nThank You\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/128512/11", "user": "VIP_Master", "ts": 1342904655000, "tid": 128512, "pn": 11}}', 1342904655000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1073410-me398', 'stk-user2057', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nطبعاً إلى الآن ما زال القسم سيء والتشيرمان أسوأ هو وزمرته عبداللطيف وبازون 😞\n\nالبروقرس ريبورت سلمك الله ماله فورم معين في الميكانيكل لكن المتعارف عليه هو ان البروقرس ريبورت يكون مختصر يشرح وش سويت خلال الفترة الماضية اللي قطعتها من التدريب.\n\nأنا عني اتذكر كان البروقرس ريبورت 20 صفحة لان الكوأب ريبورت كان مفتوح ومهو محدد بعد صفحات معين , وبعد ما كتبت حدود 80 صفحة للفاينل ريبورت قالوا لنا ماكسيمم 40 صفحه وخذلك يا زر ديليت خخخخ\n\nعشان كذا أنا بقدم لك مشورتي والطريقة اللي كنت ماشي عليها مع اختلاف عدد الصفحات:\n\n-الفيرست كوأب ريبورت :\n\nانصحك بكتابة 10 صفحات فقط تكون عبارة عن انترودكشن بسيط للشركة والقسم وانك بديت تتعرف على كيفية العمل ووش استفدت خلال الفترة الماضية وانك استفدت قيم كثيرة منها الالتزام وروح العمل والفريق الجماعي ( حشو نقدر نقول )\nوتكتب عن القسم ( البارت التكينيكال حدود 5 صفحات ) اللي كنت تسويه من عمل في تخصصك ( كتعريف بالنشاط اللي تقوم فيه )\n\n- السكند كوأب ريبورت :\n\nانصحك بكتابة 10 صفحات منها انترودكشن نص صفحة فقط والباقي تخليه اكثر تكينيكال وتتحدث عن مشاكل واجهتك وانك حليتها سواء كانت في الدوام مع زملاك او في العمل نفسه ولكن لا تففص في المشاكل التقنية بتعمق لانها راح تكون ( آز كيس ستدي ) فوفرها للاخير\n\n- الفاينل كوأب ريبورت :\n\n10 صفحات فيرست بروقرس ريبورت + 10 صفحات سكند ريبورت = 20 صفحه جاهزه\n\n5 صفحات خليها كأنها بروقرس ريبورت ثالث ولكن صغير جدا + 15 صفحة للكيس ستديز\n\nالمجموع = 40 .\n\nوتذكر ترى أهم شي الكيس ستديز قد ما تقدر جب لهم كيس ستديز حتى لو تخلي العشرين صفحة الاخيرة كيس ستديز … ولكن إن ما قدرت تدبر كيس ستديز كثيرة ف انصحك تخلي 5 صفحات كبرورقرس ريبورت ثالث وصغير.\nوبالتوفيق لكم والله يعينكم على هالقسم المتخبط ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/128512/20", "user": "user2057", "ts": 1343548757000, "tid": 128512, "pn": 20}}', 1343548757000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1390811-me398', 'stk-user4632', 'ME 398', 'info', '{"desc": "انا طبقت كواب في الشركة\nوتخصصي ميكانيكل\nكمهندس مدني صراحة مدري وش يبغون فيك ههههههههه\nيعني هي الصراحة تصلح اكثر شيء للكهرباء والصناعية\nالميكانيكل كنا نشتغل في قسم التصنيع\nرواتبهم فل باكيج بين 10800 الى 12000\n-------\nاتذكر فيه مصلى كانت فيه مخططات المطار والمناطق المجاورة مدري وش دخل الشركة تحتفظ فيها\nتاكد من القسم اللي بتروح له… لانها غريبة جدا والله\nوالله يوفقك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/164084/2", "user": "user4632", "ts": 1408397876000, "tid": 164084, "pn": 2}}', 1408397876000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1113602-me398', 'stk-once_a_red', 'ME 398', 'info', '{"desc": "السلام عليكم\nيا شباب\nانا دخلت موقع الشركه\nبقدم على كو اب\n\nبس لقيت ثلاث اختيارات ومافهمت وش تعني\napply for an IT Internship position.\n\napply for a Supply Chain Internship\nposition.\n\napply for SBC Consultant position.\n\nفاللي عنده العلم يخبرنا وش اختار\nعلما ان تطبيقي السمستر الجاي 122 + 123\nوانا ميكانيكال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/134279/1", "user": "ONCE_A_RED", "ts": 1352285565000, "tid": 134279, "pn": 1}}', 1352285565000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1331737-me398', 'stk-abu_3zzoz', 'ME 398', 'info', '{"desc": "غالبا شلمبرجير تجي الجامعة قبل يوم المهنة باسبوع او اسبوعين ولمدة يومين او ثلاثة ايام , ياخذوا السي في ويعطوك كرت فيه موعد انترفيو , بعدها بثلاثة ايام الى اسبوع يعملوا الانترفيو ( بسيط جدا حول ال 10 دقايق )\n\nالسنة الماضية كانوا محتاجين كيميكال وميكانيكال واليكتريكال وبتروليوم وجيوفيزكس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/130496/12", "user": "Abu_3zzoz", "ts": 1392819274000, "tid": 130496, "pn": 12}}', 1392819274000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1291682-me398', 'stk-zizo_791', 'ME 398', 'info', '{"desc": "Coop opportunities at Unilever Factory in Jeddah for the following majors:\n1- MIS\n2- Mechanical Engineering\n3- Electrical Engineering\nplease send your CV to the following\nemail : hamza.zeidan@unilever.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-opportunities-at-unilever/152760/1", "user": "zizo_791", "ts": 1385053366000, "tid": 152760, "pn": 1}}', 1385053366000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473126-me398', 'stk-eng_mohammed_al-sham', 'ME 398', 'info', '{"desc": "Dear All,\n\nI am looking for Summer & Coop Engineers for the following majors:\n\nMechanical Engineering\nIndustrial Engineering\nElectrical Engineering\nIf you are interested, send you CV to: sjobs@qaryansteel.com.\n\nNote: please make sure you type COOP or SUMMER -“Major”-“Name” as subject of your email.\n\nWe are looking for candidates who really want to work & learn, no free rides!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/145", "user": "Eng_Mohammed_Al-sham", "ts": 1494766090000, "tid": 174980, "pn": 145}}', 1494766090000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1362916-me398', 'stk-eng_why_not', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nالحمد لله رب العالمين, والصلاة والسلام على سيدنا محمد الصادق الوعد الأمين, اللهم لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم, اللهم علمنا ما ينفعنا, وانفعنا بما علمتنا, وزدنا علماً, وأرنا الحق حقاً, وارزقنا اتباعه, وأرنا الباطل باطلاً, وارزقنا اجتنابه, واجعلنا ممن يستمعون القول فيتبعون أحسنه, وأدخلنا برحمتك في عبادك الصالحين.\n\nرواد هذا الصرح العظيم أتمنى ان اكون ضيفاً خفيفاًِ عليكم اعين و اعاون و ان شاء الله تنتفعوا بهذا الموضوع البسيط\nسوف اعرض لكم تجاربي من تقديم و مقابلات مع الشركات التي اكرمني الله القبول منها مع العلم اني متخصص في الهندسة الكيميائية و متخرج الترم الماضي\n\nبسم الله على بركه الله\n\nسوف اقسم الموضوع الى 5 اقسام:\n1- كتابه الغرض من العمل مع السي في (الريسمي) خطوه بخطوه\n2- الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n3- تجاربي الشخصية\n4- الاختيار الأمثل\n5- نصائح محب\n\nالقسم الاول: كتابه الغرض من العمل مع السي في خطوه بخطوه\nلا يخفى عليكم اهميه كتابه السي في ولكن يغيب عن الكثير منا اهميه تحضير و كتابه الغرض من العمل\nIt’s called a Cover Letter or Statement of purpose\nلكي تحضر جيداً لكتابه الغرض من العمل، ينبغي عليك معرفه القسم الذي سوف تعمل فيه المقابلة\nFor example: I am going to have an interview at the project management department\nاسأل نفسك ماذا سوف تعمل في هذا القسم؟ و ماهي المتطلبات و شروطه؟\nخلال هذه الورقة تكتب طموحاتك و تطلعاتك للعمل في هذا الشركة ولماذا تريد انت تعمل في هذا القسم بالتحديد\nهذه امثله لكتابه هذه الخطاب\nhttp://jobsearch.about.com/od/coverlettersamples/a/coverlettsample.htm\nو هنا للسي في\nhttp://jobsearch.about.com/od/sampleresumes/a/sampleresume2.htm\nالجميل في هذه الأمثلة، انها متعددة لتخصصات مختلفة و يوجد بهذا الموقع بعض من النصائح المهمة و التي قد نكون غير ملمين بها\nمن وجهـة نظري المتواضعة قبولك المبدئي في الشركات يتعمد على قوه الغرض من العمل مع السي في\n\nالقسم الثاني: الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n1- التوكل على الله و الاستخارة\n2- معرفه القسم الذي سوف تقابله\n3- البحث عن عمل هذا القسم والالمام بمخرجاته\n4- معرفه نوع نشاط الشركة على الاقل ابجديات عملها\n5- الثقة بالنفس و عدم التوتر\n6- النوم الجيد قبل المقابلة لكي تكون جاهز 100٪ ان شاء الله\n\nالقسم الثالث: تجاربي الشخصية\nعملت 4 مقابلات من اصل10 ولله الحمد وهم ساتورب و سابك و ارامكو و شلمبرجير . و لقد اعتذرت من بيكر هيوز و وذرفورد و معادن و الصحراء و كريستال وهني ويل\n\nابدء اولا بشركه ساتورب\nالكل يعرف من هي ساتورب مشروع ضخم وجميل من اروع ما شهدت في قطاع النفط و البيتروكيميكال\nمع نهايه شهر فبراير 2014 انتهيت من تعبئه طلب الالتحاق (الابلكيشين) و تم الاتصال بي من قبل موظف الموارد البشرية لعمل مقابله معهم (تمت المقابله خلال اسبوع من تعبئه الابلكيشبن) و الحمد لله ذهبت الى مقر الشركة لعمل المقابلة الشخصية مع قسم الاوبريشين سينسور انجينيرز ( سعودي و جزائري) و للأمانة كانوا في قمه الاخلاق والتواضع. استمرت المقابلة لمده 45 دقيقه على النحو التالي: عرفنا بنفسك؟ ما هو تخصصك؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا اخترت هذا المشروع و ما الهدف منه؟ ارسم لنا الفلو شارت تبع الديزان؟ ماهي المنظمات الطلابيه التي اشتركت بها؟ وماذا كان دورك بها؟ هل عملت كوااب خلال دراستك الجامعيه؟ كيف ترى نفسك هنا كا مهندس فرش تنافس المئات من الخريجين لدى ساتورب و كيف ترى نفسك ك مهندس عمليات\n(Process Engineer)؟\nهل تود الحصول على الشهادات العليا؟ ولماذا؟\nوبحكم اني من انني لست من سكان الشرقية تم سؤالي هل تمانع من العمل في الجبيل؟\nو خلال يومين من المقابلة استلمت العرض الرسمي من الشركة\n\nالتجربة الثانية مع سابك\nاتممت التقديم على موقع سابك في منتصف فبراير 2014 والحمد لله اتتني فرصه للمقابلة من شركه صدف التابعة لسابك في الجبيل. بعد مقابلتي بيومين من ساتورب، ذهبت لعمل المقابلة مع صدف التي تعتبر من افضل شركات سابك. المقابلة الشخصية مع قسم الاوبريشين مدير المصنع و سينسور انجينير ( سعوديين) استمرت المقابلة لمده ساعه او اكثر بقليل. و للأمانة تم فصفصت ما تعلمته خلال دراستي الجامعية خلال هذه المقابلة ( بالعامية حللوني صح ) بدء من ماتيريال بالانس الى هيت و ماس ترانسفير و انتهاءَ بمشروع التخرج مع الاخذ بالاعتبار الكيمياء والبوليمرز. المقابلة كانت تخصصيه اكثر من شخصيه.\nالحمد لله استلمت العرض الوظيفي خلال شهر من المقابلة ولله الحمد\n\nالتجربة الثالثة مع أرامكو\nفي بدايه شهر فبراير 2014 استلمت رساله على الايميل من أرامكو (اعلان) اذا كانت لدي الرغبه في العمل لديهم. و بالفعل اتممت من التقديم من خلال موقعهم في نفس اليوم. وخلال اسبوع استلمت ايميل دعوه لحضور ميغا كامبين في فندق ماريوت بالخبر في يوم 17 فبراير حضرت المقابلة معهم. كان هناك حضور كثيف من خريجي الجامعات من داخل و خارج المملكة. بعد التسجيل عند المدخل في خلال نصف ساعه توجهت لعمل المقابلة الشخصية مع قسم OSPAS\nالمقابلة استمرت لمده نصف ساعه و كانت مع اربع مهندسين و في البداية عرفت بنفسي.ما هو تخصصك؟ متى تخرجت؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا تريد العمل معنا؟ ماذا تعرف عن قسمنا؟ هل ترغب في اكمال دراستك الجامعية؟ حدثنا عن البرامج التي تحسن استخدامها؟ هل عملت كوااب من قبل؟ وقد اعلموني اني سوف استلم من هم رد قريبا. و بالفعل استلمت الموافقة الرسمية ولله الحمد من القسم خلال نهاية اليوم من احد المهندسين الذي كان موجود في المقابلة.\n\nالتجربة الرابعة شلمبرجير\n\nفي البداية هذه بعض النصائح من موقع الشركة\nhttp://careers.slb.com/experiencedprofessionals/~/media/Files/Careers/leaflets/Interview%20tips.ashx\nللتحضير لمقابله هذه الشركة العملاقة استعنت بمواقع ساعدتني كثيراً للتحضير الأمثل\nhttp://www.glassdoor.com/index.htm\nحيث بالإمكان البحث عن اي شركه عالميه لاستعراض تجارب، مقابلات، رواتب (البعض منها) واشياء مفيده من الممكن ان تخدمك لأخذ إنطباع أولي عن أي شركه عالميه\nوهذا الرابط بالأسفل يعطي بعض من التجارب الجميلة لمتقدمين لشركه شلمبرجير\nhttp://www.glassdoor.com/Interview/Schlumberger-Field-Specialist-Interview-Questions-EI_IE588.0,12_KO13,29.htm\nتجد عن المتقدمين للكواب او فرش او خبير من مختلف دول العالم\nوهنا بعض الأسئله مع الاجوبه المحموده و المذمومه ومدى تأثيرها على المقابله بالإضافه لبعض المواقف و النصائح\nhttp://interview-questions1.co.uk/Schlumberger/interview+questions\nو اخيرا هذا الموقع يشرح ما يمكن توقعه خلال المقابله مع بعض الإرشادات و التعليمات\nhttp://www.petroleum-engineering.net/schlumberger-interview-how-schlumberger-will-interview-you/\n\nاتممت طلب الالتحاق عن طريق موقعهم في نهايه مارس 2014 وجاني اتصال منهم بعد اسبوع استمرت لمده ساعه. كلمتني موظفه الموارد البشرية لمده ساعه تقريباً. في البداية قالت لي تحدث عن نفسك؟ ما لذي دفعك لطلب الالتحاق لـ شلمبرجير ؟ هل عملت كوااب؟ ماذا تعرف عن شلمبرجير ؟ هل لديك مانع في العمل في الفيلد؟ او العمل في مواقع مختلفة؟ هل تمانع في العمل في داخل و خارج المملكة؟ ماهي اللغات التي تتحدثها؟ و أين تعلمتها؟ حدثني عن دراستك؟ هل شاركت في أعمال تطوعيه؟ ماهي نقاط ضعفك؟ قوتك؟ ما رايك في العمل الجماعي و الفردي؟\nوقبل إنهاء المكالمة دعتني لحضور مقابله شخصيه في الشركة في نفس الأسبوع (بعد يومين). و هنا نأتي للمقابلة الثانية\nحضرت لمقر الشركة وقابلت 3 مهندسين من جنسيات مختلفة مع موظفه الموارد البشرية. كان عدد المتقدمين 7 في ذلك اليوم ومن تخصصات مختلفة. الهندسة الكهربائية و الصناعية و الكيميائية و الميكانيكية و الكومبيوتر. هذا أعطاني الانطباع المبدئي عن هذه الشركة لأنها تريد مهندسين من تخصصات مختلفة تدربهم و تصنع منهم ما تريد في خلال الثلاث سنوات الأولى من عملهم. قابلنا المهندس محمد الخضري (إنسان في قمه اللباقة و الاحترام) و قدم لنا لمحه بسيطة عن الشركة لمده ساعه تقريباً. و بعد ذلك بدائنا الامتحان المقدم من الشركة ( انجليزي، رياضيات، ميكانيكا، فيزياء كهربائية، أسئلة عامه) استمر الاختبار لمده ساعتين تقريباً. و عندما تم الانتهاء من الاختبار تم تقسيمنا إلى مجموعتين 3 و 4. تم إعطائنا 20 ورقه و مقص و لصق و مسطره. المطلوب كان أن نبني برج لا يقل طوله عن 20 سم و باستطاعته أن يتحمل أكبر عدد من كور الجولف. المغزى من هذا العمل غير الظاهري هو العمل لإنجاز مشروع بمواصفاته المطلوبه ولكن الغير ظاهر هو مهارات العمل و الإتصال مع الاخرين ( الليدرشيب و التيم ورك) و بعد الإنتهاء من هذا الجزء كل فريق قدم عمله على طريقه (البرزنتيشين) . أخذنا بريك لمده نصف ساعه للغذاء و صلاه الظهر. بعد ذلك مباشره تم البدء لعمل المقابلات الشخصيه. في البداية عملت برزنتيشين عن نفسي ( مقدمه، السينيور ديزاين، الكواب) و بعد ذلك تم سؤالي نفس أسئلة المقابلة الهاتفية في خلال 10 -15 دقائق. لم نتطرق إلى الدراسة او مواد التخصص بشكل دقيق لكن تم التحدث عن طبيعة العمل لديهم. عرضوا علي البدء في العمل لديهم في اوروبا الشرقية او البرازيل ( بحسب احتياجهم) و من ثم عرضوا علي منهجيه العمل ( 4 اسابيع عمل و 3 اسابيع إجازة) في اول سنه وخلال السنتين الأخريين سوف يتم تحديدها لاحقاً. المسمى الوظيفي سوف تكون مهندس ميداني و ارفقوا لي بعض الأمثلة التي تشرح مهمه عملي . و في النهاية قالوا لي ننتظر منك الرد في خلال أسبوع سواءً بالموافقة او بالرفض. المقابلة استمرت أكثر من نصف ساعه و الحمد لله على كل حال\nبلغت بالموافقه المبدئيه للعمل في الشركه بعد 4 أيام من المقابله وطلب مني الحضور لبدء الفيلد اكسبوشر لمده أسبوعين مع الكشف الطبي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-z/160911/1", "user": "ENG_WHY_NOT", "ts": 1399596425000, "tid": 160911, "pn": 1}}', 1399596425000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1540769-me398', 'stk-anonymous34', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته مسّاكم الله بكل خير جميعًا.. أخواني أنا طالب في جامعة خارج المملكة وعندي فرصة تدريب تعاوني وجاتني أكثر من فرصة وحاب آخذ رأيكم وتوجيهاتكم فيها،\n\nقبلها حاب أوضح تخصصي هو هندسة ميكاترونكس، يجمع بين الميكالنيكال والالكترونيكس وشوي الكتريكال مع بعض ومجالات العمل روبوتيكس، درونز، سيارات كهربائية، أي شيء يجمع بين الإلكتريكال والميكانيكال، أو الإلكترونيكس والميكانيكال.\n\nبخصوص الفرصه الأولى جاتني في أرامكو في قسم ال Geological Operations Dept, Ground Water Div.\n\nحاولت أبحث عن القسم ماعرفت عنه كثير لكن سمعت إنه فيه روبوتيكس وبالتالي طمنني شوي لأن خفت أتدرب في شيء ماله علاقه بتخصصي ونسيت أذكر مقر العمل في الظهران.\n\nالفرصة الثانيه في ينساب في ينبع، المميز بهذي الفرصه إني راح أقدر أتدرب بالكنترول سيستمز وأعرف وأتعلم أكثر عن أنظمة الكنترول والplc وغيرها.\n\nشيء أخير نسيت أذكره، انا إنسان يهمني التوظيف بعد التدريب لو شديت حيلي معهم.. وسألت مهندس في سابك وقال لي إن وضع الشركه مو أفضل شيء وإنه السهم كان ب ١٠٠ وصار ب ٥٠، وصايرين مايوظفون نهائيًا ولو وظفو يوظفون فقط طلاب برنامج السكولارشيب. وجامعتي مو من ضمنها.\n\nبخصوص أرامكو العكس، سمعت إنه عادي يوظفون اللي يكون شاد حيله معهم.\n\nأفتوني إخواني الكرام محتار بصراحه ولكن ما أستغني عن آرائكم وإقتراحاتكم الكريمة.\n\nملاحظه مكان العمل مايهمني.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/187998/1", "user": "anonymous34", "ts": 1767263816067, "tid": 187998, "pn": 1}}', 1767263816067, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p697251-me398', 'stk-brhom', 'ME 398', 'info', '{"desc": "الي سمعته من الشباب ان جون سميث هذا ماله وجود اصلا وان هالايميل الي جا هو عبارة عن هكر !!!\n\nرمادي ماكان يدري بالسالفه…لما عرف … انبسط وقال ايه سوو ويكلي ريبورتس بس لا ترسلونها لي ارسلوها لـ coop101@gmail\n\nوهذا اخر ايميل من رمادي\n\nDear Students With refrence to the last message that was sent out to you by the Dept Coop Progress REport Monitor ( so -called John Smith alias name ) , kindly be advised as follows ;\n\nThe NEW weekly summary report is to go DIRECT to the coop Progress Report Monitor , email copied in this message and NOT to me.\nTHe weekly report is a basic and Simple standardised format that I would like you ALL to follow pls as per the headings below, and it should not take more than 10 minutes of your time to do this ON A THURSDAY at the end of the working and training week.\nUse BULLET POINT SUMMARY : FORMAT HEADINGS TO BE USED : a. Student Name and ID b. Company name and location for training c. Period of weekly REport( dates) d. Key activities done in past weeke. New initiatives or tasks carried out in last week :\nYou are still obligated to do your REGULAR FULL LENGTH PROGRESS REPORTS WITH COPIES TO ME AND TO YOUR COOP ADVISORS with cc TO THE COOP PR MONITOR, as I have noticed a lot of you still DO NOT COPY THE PR MONITOR and you might be penalised. I hope the above is clearer now. Regards and have a good coop …Dr Ramady Coop Coordinator", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/new-coop-guidelines/93787/16", "user": "BRHOM", "ts": 1283679223000, "tid": 93787, "pn": 16}}', 1283679223000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1080234-me398', 'stk-night_wolf', 'ME 398', 'info', '{"desc": "انا راح اجاوبك بحكم تخصصي ميكانيكال و حاليا اطبق في شركة بكتل مشروع معادن في راس الخير.\n\nس1/ ماهي افضل الشركات للكو أب من ناحية العمل الجاد والتطبيق الفعلي؟\n\nفي كثير من الشركات الصغيره تشغلك لكن الشركات الكبيره قليل جدا … من الشركات اللي راح تعاملك ك موظف و على حسب الديبارتمنت شلمبرجير و بكتل\n\nس2/ ما هي افضل شركة من ناحية الكافأة أثناء التطبيق؟\n\nم اعتقد في افضل من بكتل من هالناحيه مكافأتهم 5000 غير الاوفر تايم توصل الى 6500 ريال\n\nس3/ ما هي أكثر الشركات أمانا وظيفياً؟\n\nفي كثير منها ارامكو و سابك و الشركات التابعه لها\n\nس4/ لو اردت ان اكمل دراستي في الخارج على حساب الشركة تبع بعض البرامج اللي تسويها بعض الشركات ما الشركة الأفضل واللتي تعتني بهذا الجانب خير إعتناء ؟\n\nاعتقد ارامكو و يعتمد على المسؤول و الديبارتمنت اللي انت فيه و احتياجهم\n\nس5/ هل توفر لي الشركة سكن اثناء التطبيق ؟ وإذا كان الجواب لا فهل استطيع البقاء في سكن الجامعة بشكل رسمي لو كان التطبيق في الظهران ؟\n\nبعض الشركات توفر و البعض لا … يعني ارامكو و بكتل يوفرون لكن سابك لا و هم يعتمد على المنطقه اللي انت فيها اذا كانت بعيده معظم الشركات توفر لك\n\nس6/ ما هي المميزات والحقول اللي يتمتع بها طالب الكو أب ؟ أقصد هل الشركة توفر للطالب مصاريف البحوث والتقارير لو إحتاج إلى ذلك ؟\n\nالمتدرب عادة م يلقى الاهتمام اللي هو يتوقعه و لكن متى م حصلت لك فرصه في العمل و اثبت جدارتك انت كذا تفتح العيون عليك و م اعتقد في شركه بتصرف لك قرش على تقاريرك . زين يعطونك مكافأه\n\nس7/ بالنسبة لشركة أراكو السعودية ماهو مقدار المكافأة الشهرية اثناء الكو أب ؟\n\nاتوقع و العلم عند الله من 2000 الى 2500 ريال\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/130182/2", "user": "Night_wolf", "ts": 1345321995000, "tid": 130182, "pn": 2}}', 1345321995000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1181222-me398', 'stk-iahmed015', 'ME 398', 'info', '{"desc": "شباب سؤال شاطح\n\nايش الكورسات اللي لازم تخلصها عشان تقدر تطلع الكوواب …\n\nانا اعرف منها :\nEngl 214\nME 307\n\nضيفوا عليها + عدلّوا لو فيها خطأ …\n\nوشكراً ❤️ 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/139645/15", "user": "iAhmed015", "ts": 1360625209000, "tid": 139645, "pn": 15}}', 1360625209000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221092-me398', 'stk-panther', 'ME 398', 'info', '{"desc": "Hi\n\nFirst of all sorry I’m using my job system so I can’t write in Arabic\n\nI took an internship in National Water Company for two months and it is similar to A-Kahraba company in sense that it is owned by the country and they both belong to the ministry of water and electricity.\n\nI don’t know you major but if you are a chemical engineer you will work at Waste Water treatment plant. Your job will be in operation so you operate the plant according to specifications to clean waste water.\nThe company has two branches: waste water treatment and potable water department.\nIf you are a mechanical engineer or electrical engineer you will most probably work in maintenance of a waste water plant.\nThe company is now run by old people from the days of the ministry and now they are hiring youths so you can go up faster than in Al-Kahraba\n\nAbout the salary I don’t remember the exact number but I think as fresh graduate you will get around SR 10,500 as a total package.\n\nHope this will help you all KFUPMers and guests", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/vs/144282/5", "user": "panther", "ts": 1368276234000, "tid": 144282, "pn": 5}}', 1368276234000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473328-me398', 'stk-vip9311', 'ME 398', 'info', '{"desc": "السلام عليكم جميعا\nاخوكم من المقبولين في شركة مرافق دفعة ٢٠١٦.\nتقريباً صار لي الان في الشركة ٦ أشهر.\nيعلم الله ان هذا المنتدى له فضل كبير في قبولي بالشركة وما قصروا شباب الدفعات السابقة في مساعدتنا، و اقل شي اسويه انه ارد الفضل بمساعدة هذه الدفعة. و بالصدفة عرفت امس من واحد انه في مقابلات راح تكون قريبة لدفعة هذه السنة فقلت خليني ادخل المنتدى اشوف كيف الوضع لانه من فترة ما دخلت. المهم كلامي كثير\n\nنجي للكلام اللي يهمكم.\n\nانا ب اعطيكم كل المعلومات اللي اعرفها و اذا بعد كذا احتجتوا اي شي اسألوا تحت هذا الموضوع و ان شاء الله راح احاول ادخل المنتدى كل يومين و اجاوب كل الاسئلة. ( يا ليت ما تسألوا في الخاص عشان يسير اجاوب في العام و الكل يستفيد لانه الاسئلة راح تتكرر ف افضل اجاوب في العام يصير الكل يشوف. )\n\nطيب خليني ابدأ بطريقة الشركة في التقديم.\n\nشفت انا فوق بعض الشباب تم التواصل معاهم عشان يرسلوا ملفات، هذه اول خطوة. الشركة تفتح التقديم الكترونيا بعد كذا يتم الفرز الكترونيا ومن خلال موظفين الموارد البشرية. يعني اللي معدله كويس و اموره الثانية تمام في امل كبير انه يتواصلوا معاه و يطلبوا منه الملفات. اللي يتواصل معاه غالبا شخص اسمه ايمن ، او محمد، او عبدالرحمن ( للخصوصية ماله داعي اذكر اسمائهم كاملة او ايميلاتهم او ارقامهم و رجاء لحد يطلبها لانه شي خاص )\nالمهم بعد ما تتم هذه الخطوة يتواصلوا معاك بعدها بفترة قد تكون اسبوعين ثلاثة شهر ع حسب المهم بعدها يتواصلوا معاك عشان موعد المقابلة.\n\nنجي للي حالفوا الحظ وتم تحديد مقابلة معاه\n\nالمقابلة صراحة الشركة جدا مهتمة فيها و راح يكون موجود مدير ادارة الموارد البشرية، مدير ادارة Human Capital Development ( ما اعرف ايش بالعربي هههههههه امزح 😁2:المهم هذه ادارة تهتم بالتدريب وكذا ) ايضا مدير من الهندسة و غالبا مدير القسم اللي راح تتوظف فيه و موظف اتش ار ( الزبدة انه اللي بيقابلك مو اي احد، ناس فاهمة و خبرة ) طبعا ما راح يكون عندك اختيار مع اي قسم المقابلة، انت و حظك. بس غالبا راح يكون قسم يحتاجوا فيه تخصصك\n\nالمقابلة نفسها راح تكون شي عام يعني شخصيتك معدلك دراستك مشروع التخرج و مديرك المباشر راح يفصل معاك في مشروع التخرج و الكوأب و مدير الهندسة راح يفصل معاك في التخصص و مواد ٤٠٠ ، يعني بالزبدة استعد كويس و افطر و اشرب قهوة و روح لهم مصحصح لانه المقابلة عندهم نص ساعة على الاقل وما عندهم مقابلة ثانية، يعني من مقابلة وحدة راح يحددوا اما ياخذوك او لا.\n\nع فكرة، الشركة تاخذ من اغلب التخصصات بس الغالب في دفعتنا كانوا هندسة كهرباء، ميكيانيكال و في واحد كيمياء عامة وفي كمان تخصصات ادارية زي محاسبة مالية مدري ايش هذا اللي شفته وفي الدفعة اللي قبلنا اخذوا واحد مدنية و واحد صناعية يعني في تنوع بس حسب اللي شفته انه كهرباء وميكانيكال اكثر شي ( ممكن اكون غلطان في دي المعلومة بس انا انقلكم اللي شايفه )\n\nطبعا بعد المقابلة وسعوا بالكم ، انا اخذوا شهرين تقريبا الين ردوا علينا، مع انهم وقت المقابلة قالوا اسبوعين و نرد. طبعا ازعجتهم اتصالات و كذا بس مافي فائدة. يعني بعد المقابلة لحد يسألني متى يردون من دحين قلت لكم مالكم الا الانتظار ، لحد يسألني دا السؤال يرحم أمكم ^ــ^\n\nطيب نجي للعرض الوظيفي و المميزات المادية\n\nبصراحة مو لاني موظف الان فيها، بس عرضهم حلو جدا مقارنة ب أماكن كثير. يعني راتب أساسي بين ١١-١٢ الف حسب امور ما اعرفها بس اكتشفت انه في تفاوت يعني ناس اعطوهم ١١ الف، ناس ١١٥٠٠ وناس ١٢ الف وممكن ناس اخذت اكثر بس ما اتوقع . طبعا هذا بس راتب اساسي ( هذه لل PDP Engineer ) سواء ميكانيكال او الكتركل، غير المهندسين صراحة ما عندي خبرة\n\nفي عندهم ٢٥٪ بدل سكن + ١٠٠٠ ريال بدل نقل\nبالاضافة عندك تأمين صحي vip من شركة بوبا ( صراحة تأمين ممتاز و يغطي تقريبا كل شي ) للموظف و زوجته اولاده + امه و ابوه بوجود صك اعالة ( سالفة صك الاعالة تافهة و بسهولة تاخذه )\nاضافة الى بونص سنوي ، العام مع الاوضاع الاقتصادية و كذا لكن برضوا جا بونص راتبين و نص وفي السنة اللي قبلها جا بونص ثلاث رواتب ، يعني شي كويس و معقول جدا\n\nالزبدة ينزل لك توتال تقريبا ( بعد خصم التأمينات ) يجي في حسابك حول ١٤ الف و شوية 😂تزيد شوية او تنقص شويات مثل ما قلت لكم حسب راتبك الاساسي\n\nبعدين لل PDP تجيه خلال مدة البرنامج ٤ زيادات، في السنة زيادتين ( كل ستة اشهر يصير فيه تقييم و بناء عليه تجيك زيادة اذا ممتاز زيادة ٧٠٠ اذا جيدجدا ٥٠٠ واذا جيد ٣٠٠ ) طبعا هذه زيادة على الراتب الاساسي، ايضا في زيادة حقت التقييم العام للموظفين ( هذه لحد يسألني فيها لانه فيها كلام كثير ان شاء الله للي ينقبل نشوفه في الشركة و اعطيه العلم ، لانه صار لنا فيها سالفة :shushing_face: )، بس مثل ما قلت هذه غير زيادات ال PDP تجيك وحدة في السنة يعني تقريبا توتال ٦ زيادات 😎\n\nطبعا المهندس يتوظف على وظيفة PDP Engineer بس طبعا يكون في القسم اللي قبله، PDP هذا برنامج زيه زي الشركات الثانية يكون فيه في البداية كورسات بعدين تروح روتيشن على عدة أقسام ووووووو كلام طويل مو وقته الان\n\nخلاص كذا كفاية 🚬 ، اذا انقبلتم ان شاء الله، بنكون زملاء و وقتها اعلمكم الاشياء الثانية لاني تعبت من الكتابة، انا حاولت اتكلم عن كل شي ممكن يدور في ذهنكم ، وترى هذه اول مرة بحياتي اشارك كذا ب منتدى بس والله اني افتكرت حيرتي وقت ما كنت اقدم في الشركة و قلت عهد على نفسي اذا اتوظفت فيها اني اساعد غيري\n\nع فكرة، انا مو من خريجي البترول بس صراحة المنتدى هذا شي جميل 👍\n\nبالتوفيق لكم و ان شاء الله اللي يروح مقابلة يتوفق في الشركة واللي ما يحالفه الحظ ان شاء الله خيرة له و ربي يوفقه في اماكن افضل\n\nو السلام عليكم و رحمة الله و بركاته :man_playing_handball:", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/marafiq-2017-pdp/176512/36", "user": "vip9311", "ts": 1495064615000, "tid": 176512, "pn": 36}}', 1495064615000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1125561-me398', 'stk-user1850', 'ME 398', 'info', '{"desc": "السلام عليكم\nياشباب صديقي طالب كواب هندسة ميكانيكية ويبي أحد يكتب له الريبورت ويتفاهم معاه بالموضوع والسعر … الموضوع يتعلق بالـpipes والكيس ستديز والريبورت بشكل عام … موعد التسليم النهائي قبل 28 يناير\nجوال الأخ عبدالله 0545858687\nوشكرا 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/135578/1", "user": "user1850", "ts": 1354059817000, "tid": 135578, "pn": 1}}', 1354059817000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1219779-me398', 'stk-che27', 'ME 398', 'info', '{"desc": "الاوبريشن انجنير هو نفسه Production Engineer وهذا مخصص للكيميكلز …\n\nالانسبكشن انجنير … أغلبهم ميكانيكلز انجنير …\n\nالميكانيكل انجنير سبورت طبعاً ميكانيكل انجنيرز …\n\nحتى لو حطوك في مكان مهو مكانك … على الاقل تعلمت شي جديد … اغلب الميكينيكل مايعرفون شي عن الاوبريشن ويضطرون يشتغلون شفتات في الاوبريشن فترة علشان يفهمون … لكن انت ميكانيكل وفترة التدريب تعلمت عن الاوبريشن … يعني إن شاء الله إذا توضفت كميكنكل (( مسؤول صيانة )) رح تكون عندك خبرة كبيرة في الاوبريشن وهذا شي ممتاز صدقني.\n\nالقسم اللي تدربت فيه ممتاز … يا ليت تشاركنا اسمه ومكانه علشان الشباب اللي ودهم يطلعون كواب للاستفادة يجون أكيد لقسمك.\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/144150/3", "user": "CHE27", "ts": 1367899962000, "tid": 144150, "pn": 3}}', 1367899962000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1038138-me398', 'stk-abo-nasser', 'ME 398', 'info', '{"desc": "السلام عليكم\nانا لحد اليوم ما سويت الشيك ليست\nتخصصي ابلايد ميكانيكال\nبروح بكره انشالله\nبازون(الكوأب كوردينيتور) ارسلت له ايميل وشكله غير متعاون هل فيه تاريخ لعمل الشيك ليست\nابغا شي احجه به اذا تكرمتم\n\nوشاكر لكم الرد مقدما واتمنى لكم التوفيق .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/125659/1", "user": "abo-nasser", "ts": 1337123004000, "tid": 125659, "pn": 1}}', 1337123004000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429987-me398', 'stk-user7794', 'ME 398', 'info', '{"desc": "إعلان عن توفر فرص تدريب تعاوني\n\nتعلن شركة ) Siemens) عن توفر الفرص التدريبية التالية في برنامج التدريب التعاوني وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n· الهندسة الكهربائية ( الرياض – جده – المنطقة الشرقية)\n· الهندسة الميكانيكية ( الرياض – المنطقة الشرقية)\n· الهندسة المدنية - الرياض\n· الإدارة (الرياض – جده – المنطقة الشرقية)\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية على الإيميل التالي: mahdi.almuammar@siemens.com\n\nإدارة التدريب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/6", "user": "user7794", "ts": 1444371403000, "tid": 170272, "pn": 6}}', 1444371403000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433091-me398', 'stk-user8890', 'ME 398', 'info', '{"desc": "Dear Students,\n\nSIEMENS****Training program offers COOP training opportunities to a limited number of high caliber Saudi students who are studying in local universities or abroad. The program has been designed to support senior students to transfer their theoretical knowledge to practical work experience in one of our divisions in three different regions (Riyadh, Jeddah and Eastern Province), as well as achieving university requirements of graduation by completing practical credits.\n\nWe are looking for both engineering and business related majors starting in Jan - Feb 2016. So for now you can share with your students the below applying links as we are not accepting CV’s through direct emails anymore:\n\nApplying link for Electrical, Mechanical and Civil engineers:\n\nhttps://careers.siemens.successfactors.eu/sfcareer/jobreqcareer?jobId=215052&company=Siemens&username =\n\nFor all business related majors:\n\nhttps://careers.siemens.successfactors.eu/sfcareer/jobreqcareer?jobId=215053&company=Siemens&username =\n\nWe are looking forward to receive CV’s of high potential candidates to be part of our training program.\n\nBest Regards,\n\nMahdi Almuammar\n\nRecruitment Manager\n\nSiemens Ltd. SA\n\nBusiness Gate, Building C-1\nAirport Road, Qurtubah District\nP.O. Box 9510, Riyadh 11423\nSaudi Arabia", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/28", "user": "user8890", "ts": 1447332867000, "tid": 170272, "pn": 28}}', 1447332867000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1269897-me398', 'stk-user7795', 'ME 398', 'info', '{"desc": "اسمح لي يا صاحب الموضوع عندي استفسار لا هنت\n\nانا فريشمان جديد\n\nدايماً أسمع بالكو اب والسمر تريننق\n\nلكن ما أعرف الفرق بينهم (اللي اعرفه اني لازم اخذ سمر تريننق بعد السفمور او الجونيور)\n\nلكن هل الكو اب اجباري (وشنو الكو اب اصلا)؟\n\nمع العلم ان تخصصي علوم في الهندسة الميكانيكية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/150207/6", "user": "user7795", "ts": 1380521445000, "tid": 150207, "pn": 6}}', 1380521445000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p924907-me398', 'stk-majcom', 'ME 398', 'info', '{"desc": "بالنسبة لك اخوي cortez1408\n\nاولا ماشاء الله تبارك الله و بالتوفيق للجميع\n\nشركة الربع الخالي الصراحة ما اعرف عنها اي شيء\n\nاما بالنسبة لشلمبرجير و GE الاثنين من افضل الشركات …\n\nGE حسب ما سمعت انها افضل شركة مزودة للمعدات الكهربائية على مستوى العالم\nطبعا فيها شغلات ميكانيكة واجد لا تخاف (شغلات تورباين و غيره)\n\n-الشركة امريكية و معروفة لا غبار عليها رواتبها مغرية (سمعت 14 الف فل بكج) و الله اعلم\n-عندهم برامج تدريبة على مستوى عالي جدا\n-امكانية ان تشتغل في نفس تخصصك بما انك هندسة ميكانيكية\n-كل اللي اخذوا COOP في هالشركة يمدحون فيها\n\nبالنسبة لشلمبرجير فانا اشتغلت معاهم فترة بسيطة و كانت تجربة حلوة صراحة\nلكن هذا يعتمد على الشخص نفسه\n\n-هل عندك القابلية ان تشتغل في مناطق نائية وسط الصحرا ء او وسط البحر ؟\n- و بنظام الشفتات او حتى on call ؟\n-لساعات طويلة (12 ساعة على الاقل) و اذا وايرلاين اطول اكيد\n-هل عندك مشكلة انك تشتغل خارج اطار تخصصك ؟\n- هل عندك مشكلة تعمل في بيئة خطرة (احتراق ، غازات سامة …الخ)؟\n\nكل هالامور لازم تاخذها بعين الاعتبار و اما ميزات شلمبرجير فهي تماما مثل ge من ناحية\nالتدريب و الترقية …الخ\n\nطبعا لما نجي نقارن بينهم\n\n- فسنجد أن الميزة الوحيدة لشلمبرجير على GE هو الراتب <<< و هذا يمكن يكون سبب كافي للبعض بان يفضل الشركة هذي\nو ربما يكون سبب غير كافي للبعض الآخر ، و زي ما قلت انه يعتمد على الشخص نفسه\n\n- لكن شلمبرجير فيها عيب ، انه خلاص هذي بتكون خبرتك (محدودة) في مجال معين\nبعدين راح يكون صعب انك تغير\n\n- اما GE فمشاريعها تدخل في ال power plant و petrochemical بالاضافة الى oil & gas\nيعني الخيارات عندك اكثر في المستقبل\n\nاسف اني طولت عليك … في الاخير القرار المناسب يعتمد على الشخص نفسه و على\nالاشياء اللي تهمه و اللي بيحصل عليها من الوظيفة نفسها .\n\nبالتوفيق للجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/114286/7", "user": "majcom", "ts": 1319477766000, "tid": 114286, "pn": 7}}', 1319477766000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1370161-me398', 'stk-soros', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته 🌹\n\nياشباب الي مالقى شركه ويبي يطبق coop بالرياض\nفي مقعد واحد وابي اخدمكم فيه\n\nاي واحد يبي الفرصه يتواصل معي على الخاص ويرسلي رقمه\nطبعا هندسه ميكانيكيه ومعدلك فوق 2\n\nتمنياتي للجميع بالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/161601/1", "user": "SoRoS", "ts": 1400876938000, "tid": 161601, "pn": 1}}', 1400876938000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1095878-me398', 'stk-ibra1991', 'ME 398', 'info', '{"desc": "بحسب نادي الهندسة الميكانيكية راح يعملون برنامج من ثلاث ايام عن الكواب والسمر تريننق كل يوم محاضرة يستضيفون طلاب اخذوا الكورس والدكاترة المسؤليين لكن بنسبة لك اعتقد انه غير مناسب لانهم يقولون ان البرنامج\nبعد الاسبوع الحادي عشر كذا مايكون عندك وقت كافي انك تعمل الاجراءات. بتكون بين مواعيد ميجر تو و التجهيز للفاينل\nالحل إنا نجتمع ونكلم المسؤولين يشوفون لنا حل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/132177/2", "user": "ibra1991", "ts": 1348072896000, "tid": 132177, "pn": 2}}', 1348072896000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1122710-me398', 'stk-mka22', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nجزء من الرسالة اللي وصلتني عن طريق ايميل الجامعة :\n\nIf you intend to early register for Coop, then you should add course # 350 in term 122 and course # 351 in term 123 during the early registration period\n\nExample: If your major is AME, then add ME 350 in term 122 and ME 351 in term 123.\n\nالمشكلة إن مادة me351 فقط موجودة في ترم 122 (me350 غير موجودة)\nوالترم الصيفي غير موجود أصلا للتسجيل\n\nيا ريت اللي عندة أي معلومة بخصوص المشكلة يذكرها هنا 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/135310/1", "user": "mka22", "ts": 1353759866000, "tid": 135310, "pn": 1}}', 1353759866000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p238166-me398', 'stk-user3237', 'ME 398', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته\n\nاسعد الله اوقاتكم\n\nانا ياشباب طالع coop\nالسمستر الجاي وقبلتني سابك واليوم دقت علي شركه General Electric فرع الدمام وقالوا لي قبلناك والان انا محتار ايهم احسن فإذا احد طبق في هالشركه من قبل ولا يعرف عنها شي يردلي\n\nباسرع وقت (تخصصي ME )\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-general-electric/61003/1", "user": "user3237", "ts": 1201002219000, "tid": 61003, "pn": 1}}', 1201002219000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1335601-me398', 'stk-aziz_saleem', 'ME 398', 'info', '{"desc": "ما عليك انت دور على شركة و خذ العرض من عندهم و كل شي لأنه الأبروفال يمشيه لك قسم التدريب و بيكون شي جيد لو معاك فرصة جاهزه , مو لازم تاخذ موافقة بازون إلا لما تعطيه الخطة ( لما تبدأ التدريب) , و الأبروفل وضعه بسيط يمديك توقعه من القسم و تخليه عند قسم التدريب و تعطيهم قريداتك اذا خلصت الترم هذا عشان يمشوا الأبروفال ,\nالوضع سهاله ان شاء الله انت بس جيب معدل عالي الترم هذا و ربي يوفقك ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/157656/4", "user": "aziz_saleem", "ts": 1393690297000, "tid": 157656, "pn": 4}}', 1393690297000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1335736-me398', 'stk-_16', 'ME 398', 'info', '{"desc": "1-تروح تاخذ ورقة (Chick list) وبما ان معدلك تحت ال2 تحتاج ورقة(Potion form )\n2-تعبيها وتوقعها من ادفايزرك ومن الدكتور/بازون ومن الديبارتمنت\n3-تروح قسم التدريب وتعطيهم الاوراق يوقعونك على وقة انك تخلي الاوراق عندهم لنهاية الفصل ويعطونك اوراق ترسلها للشركات تقدر ترسها بالفاكس حق قسم التدريب لاي شركة تخاطبها\n4-بنهاية الفصل اذا ماجاك دسمس لاسمح الله تروح قسم التدريب تاخذ الاوراق وتوقعها من مبنى 21\nهذي كل الاجراءات اللي تسويها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/157656/6", "user": "_16", "ts": 1393715788000, "tid": 157656, "pn": 6}}', 1393715788000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1166416-me398', 'stk-user8386', 'ME 398', 'info', '{"desc": "السلام عليكم …\n\nصبحكم الله بالخير … أنا يا أخوان قدر الله علي وقبلت في شركة هاليبرتون للتدريب التعاوني . تخصصي هندسة ميكانيكية\n\nإذا أمكن يا شباب تفيدوننا عن هالشركة للي أخذ تطبيق فيها … وين مكان العمل وهل فيه رحلات برية صحراوية والا فقط بالدمام .\n\nوهل تنصحوننا فيها والا نفرك لشركة ثانية .\n\nتشكرات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/138603/1", "user": "user8386", "ts": 1358643303000, "tid": 138603, "pn": 1}}', 1358643303000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p720909-me398', 'stk-user2728', 'ME 398', 'info', '{"desc": "- يزودنا باسم شركات معروفه بقبولها للطلاب للكوأب\"وامتيازات كل شركة\"\n\nما في شركات معروفة ممكن تخليك تطبق خارج المملكة\nحسب تصنيفات بعض الشركات\nفي واحد من طلاب الالكترك طلع امريكا مع شركة جنرال الكترك (على ما أظن)\nوفيه شركات أخذت 6 طلاب ميكانيك وودتهم أوروبا\nوفيه شركة jgc\nأخذت طالب من كل تخصص هندسي وودتهم الفلبين بعدين اليابان\n\n- معلومات عن المصاريف اللي يحتاجها الطالب بالخارج\n\nالمصاريف غالبا تكون معيشة من اكل وشرب وغيره\nالسكن يوفرونه لكم الشركة والجامعة تعطي فلوس مقدم ( ما أدري كم ) غير مكافأة الجامعة وغير مكافاة الشركة\n\nطريقة التقديم تكون عن طريق إدارة التدريب بمبنى 17 يعلنون لكم وتكون الاعلانات مبكرة\nهذي تكون احتمالية قبولك ضعيفة جدا لان المقاعد محدودة وما يقبلون الا ذوي المعدلات العالية\n\nوفيه تقديم عن طريقك أنت تراسل بها الشركات، يعني تاخذ الموافقة من عندهم بنفسك وتكمل باقي الاجراءات معهم ومع ادارة التدريب\nهذي بالنسبة للشركات يفيدونك فيها قسمك نفسه من رئيس أو دكتور لان لهم علاقة مع الشركات الخارجية\n\nحاول تبدا بهالامور بدري لان الشغلة احتمال تطول خصوصا مع استخرج الفيزا من السفارات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96672/2", "user": "user2728", "ts": 1286981241000, "tid": 96672, "pn": 2}}', 1286981241000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1452524-me398', 'stk-user10675', 'ME 398', 'info', '{"desc": "اهلًا وسهلا فيك الموحد بالله\nهذا الاستبيان فيه تخصصات هندسية ذكرت كالهربائية والكيميائية والصناعية وهذا لا يدل على انها ماهي مرغوبة او ان التخصص مشي حالك. بل انا اشوف انها تخصصات قويه ولا يستهان فيها.\nانا كمبتعث في امريكا من 2011 وهذا اخر ترم لي هندسة ميكانيكية، اشوف ان الشركات الامريكية هنا ما تطلب ولا تفضل الا المهندس. والطلب هنا مستمر على المهندسين بكل تخصصاتهم والكلام يشمل كندا ايضا. والسبب هو ان معرفتي بان هذي الدولتين اقتصادها متنوع كمثال( اعتمادهم على الفحم الحجري، الطاقة المتجددة بكل اشكالها،الجيوثيرمال،التصنيع، البترول، الغاز…الخ) وهذي كلها تحتاج مهندسين. اضافة ان الطالب الامريكي هنا وهو على رأس الدراسة تلقاه يستغل كل فرصه عمل عشان يضيفها في السي في كخبرة(فتلقاه يستغلو الكواب والانترنشب الي هي فرص التدريب ويشتغل كريسيرشر الى هو باحث مع احد مدرسينة وياخذ كلاس يعلمه كل التطبيقات الهندسية الي عن طريق الكمبيوتر ويحترفها ويشتغل كموظف عادي في احد مكاتب الجامعه بعمل جزئي) فيتخرج مهندس ومعه خبرات عمل كثيرة ولو كانت فترات عملها قصيرة. هذا النوع من المهندسين يقدر يتوظف باي مكان في العالم.\nالسعودية في الماضي ( تقريبا قبل 7سنوات)الي يتخرج ب 2من4 وبدون خبرة، يتوظف في اطلق الشركات كأرامكوا وسابك. بس اليوم بما ان اقتصاد السعودية شبه معدوم بسبب اعتمادنا ع البترول والغاز واعداد خريجين الهندسة زاد… صار في مشكلة بالتوظيف. وأكثر الخريجين معدلاتهم ممتازة ولكن للاسف ما معه اي خبرة.\nفأنت اخوي النصيحه الموجهه لك بعد هذا الكلام الطويل، هو انك تبدأ تصنع مستقبلك ابتداء من اليوم.\nإِيش تقصد؟ يعني انك ما تفوت اي فرصه كواب او انترنشيب او فرصه عمل داخل الجامعه اثناء دراستك عشان لما تخرجت تكون مميز وتلفت الانتباه لك اكثر. وبالعكس قد تصل انك تكون مرغوب بشركات من برا السعودية بعد، بحكم انك شخص مميز وفريد من نوعه.\nاعتذر عن الاطاله لكن حبيت اني أوضح لك بالتفصيل الممل.\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2015-2016/173678/16", "user": "user10675", "ts": 1466525713000, "tid": 173678, "pn": 16}}', 1466525713000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1517931-me398', 'stk-user8797', 'ME 398', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته\n\nفرصة للعمل في شركة نمذجة للتصنيع بالإضافة، شركة ناشئة متخصصة في مجال الطباعة ثلاثية الأبعاد وتصنيع المنتجات المبتكرة. مجال العمل مرتكز على الإبتكار و سيؤثر بشكل جذري في عالم التصنيع خلال السنوات القادمة.\n\nإذا كنت شخص تحب الابتكار و تجربة الغير المألوف فهذا المجال يناسبك.\n\nالفرص المتوفرة:\n\nهندسة ميكانيكية / تدريب تعاوني\nعمارة / تدريب تعاوني - توظيف\nتسويق-إدارة أعمال / تدريب تعاوني - توظيف\nللتقديم: jobs@namthaja.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/182439/1", "user": "user8797", "ts": 1576176487000, "tid": 182439, "pn": 1}}', 1576176487000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1491905-me398', 'stk-engibrahim', 'ME 398', 'info', '{"desc": "بالنسبة للمقابلة ( ميكانيكال )\n\nكانت مقابلة خفيفه ولطيفة … اللجنة مكونه من ثلاث اشخاص والبداية كانت عرف عن نفسك بعدين سالوني عن وظيفتي السابقة وليه تركتها عن التدريب التعاوني ومشروع التخرج ايضا كان فيه سوال عن الدورات اللي كانت بالCV\nايضا كان فيه سوال ماعندك مشكله تتوظف باي مكان\n\nهذا والله اعلم\nفالنا وياكم التوفيق 👋", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/178510/156", "user": "EngIbrahim", "ts": 1525684276000, "tid": 178510, "pn": 156}}', 1525684276000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483867-me398', 'stk-acheng', 'ME 398', 'info', '{"desc": "\"إعلان عن توفر فرص تدريب تعاوني\n\nتعلن شركة شيفرون ومقرها الجبيل عن توفر فرص تدريب تعاوني وبالتنسيق مع إدارة التدريب بعمادة شؤون الطلاب للتخصصات التالية:\n\n· الهندسة الميكانيكية\n\n· الهندسة الكيميائية\n\no شروط التدريب: الشركة تشترط ان يكون المعدل 3 فما فوق للطلاب المتقدمين\n\no مميزات التدريب: راتب شهري (3500 ريال)\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية للشركة على البريد الالكتروني:\n\nALMASA@saudichevron.com\n\nإدارة التدريب\n\nعمادة شؤون الطلاب\n\nجامعة الملك فهد للبترول والمعادن\"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/172-173-181/177905/23", "user": "ACHEng", "ts": 1511697267000, "tid": 177905, "pn": 23}}', 1511697267000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1496032-me398', 'stk-muhanad_alhazmi', 'ME 398', 'info', '{"desc": "شوف يا طويل العمر. راح اعطيك رأيي مع العلم أنني حديث تخرج ولست من ذوي الخبرة.\n\nبيكرهيوز في الوضع الحالي تعتبر أحد شركات جنرال إليكتريك. أخذت الكواب حقي مع جنرال إليكتريك العام الماضي مع العلم أنني هندسة ميكانيكية. طبعا جنرال إليكتريك في العام الماضي كانت تمر بتغيرات مما سببت مشاكل في توقيف بعض الفرص الوظيفية فكان وقتها الفرص الذهبية في بيكرهيوز بسبب إرتفاع أسعار النفط إلى حد الآن. عشان تكون في الصورة جنرال إليكتريك سرحت كثير من الموظفين فبعض الموظفين الذين كانو على علم أن الشركة ستسغني عنهم للأزمة المالية قامو مباشرة بالذهاب إلى بيكرهيوز بسبب أن وضعها ممتاز وكانت شركة ممتازة قبل الشراكة مع جنرال إليكتريك.\n\nبكل بساطة لما كنت كواب كان عندهم بعض المناصب الهندسية بمسمي specialist للتخصصات الهندسية ولم أقدم عليها بسبب المسمى وكان ال HR في جنرال إليكتريك وهو شخص مجتهد ومحل ثقة يقول لي أن المسميات في الشركات التابعة ل جنرال إليكتريك لا تمت بصلة للتخصص الوظيفي. مثلا: اسمك specialist لكن في الواقع انت مهندس محترف في الشركة. وهذا للأمانة أنا لاحظته لما كنت كواب كنت أشوف أسامي فخمة جدا وهو ليس بتلك الفخامة والعكس صحيح!\n\nمن وجهة نظري شوف حساباتك وماذا تفضل مع العلم أن المسمى الوظيفي في أي شركة تابعة لجنرال إليكتريك لا يحدث ذلك الفرق. النقطة المهمة أن جنرال إليكتريك أعلنت في الأونة الأخيرة انها سنتهي شراكتها مع بيكرهيوز وستعود بيكرهيوز مستقلة كما كانت. في هذه الحالة يفضل الإتصال بال HR الي رسل لك ال offer من بيكرهيوز ومناقشة قضية المسمى بكل شفافية لكي تكون على بينة.\n\nأسال الله لك وللجميع التوفيق والسداد. 😀", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/179746/2", "user": "muhanad_alhazmi", "ts": 1532000644000, "tid": 179746, "pn": 2}}', 1532000644000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1469124-me398', 'stk-s.ebrahim', 'ME 398', 'info', '{"desc": "السلام عليكم\n\nحاب انقل لكم تجربتي في الشركة الي تدربت فيها تدريب تعاوني (شركة اسمنت الشرقية).\n\nقبل بداية التدريب حاولت ابحث على معلومات عن الشركة فما لقيت شي لا بالمنتدى ولا بالشيخ قوقل والحين بعد ما انتهيت تدريب قلت انقل لكم تجربتي.\n\nاجراءات القبول كانت بسيطة رحت الفرع الرئيسي بالخبر وقابلت الHR وطلب مني بعض الاوراق (صورة من بطاقة الاحوال و صورة من الايبان للمكافأة الشهرية وكانت 2000 ريال) وبعدها علمني وقت ومكان الدوام.\n\nفي اول يوم دوام رحت لهم بلانت في منطقة الخرسانية (تبعد عن الدمام 160km تقريبا) وقابلت الplant maneger واعطاني نبذة عن المصنع وبعدها حولني لقسم التدريب. طبعا موظفين الHR وباقي الموظفين الي بالمصنع ما كان عندهم علم ان في طلاب راح يتدربوا بالمصنع فصارت لخبطة في اول يومين.\n\nالتدريب كان في 4 اقسام: التدريب / المحاجر / الصيانة / الانتاج .\n\nقسم التدريب جلست فيه تقريبا مابين ثلاثة الى اربعة اسابيع واخذت فيه عدة كورسات ومنها كورسات في السيفتي والايزو\n\nالشي الحلو في الكورسات ان بعد كل كورس تاخذ شهادة تدريب وهالشهادة راح تفيدك بالتقديم بعد ماتخلص جامعة.\n\nقسم الصيانة اكثر قسم جلست فيه بحكم ان تخصصي هندسة ميكانيكية واكثر قسم استفدت منه من ناحية المعلومات.\n\nبقية الاقسام مريت عليهم عالسريع اخذت فكرة عنهم ووش مسؤوليات ومهام كل قسم.\n\nنجي للدوام ، دوامك اغلبه ميداني تطلع مع المهندس تشوف المشاكل الي بالمصنع وكيف يتعاملوا معها. وقت الدوام كان شوي متعب لأن الشركة كانت متشددة في مسألة الحضور والانصراف لدرجة انهم يعاملوك معاملة الموظف ، طبعا الدوام بصمة من الساعة 7:00ص الى الساعة 3:00 م .\n\nالشركة بالنسبة لي كانت ممتازة من ناحية التدريب واستفدت اشياء كثيرة في التخصص ، ولكن مايعيب الشركة ان ما فيها اماكن مخصصة للطلاب فكل مرة تدور لك على مكان تجلس فيه.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/176178/1", "user": "S.Ebrahim", "ts": 1488198029000, "tid": 176178, "pn": 1}}', 1488198029000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1513930-me398', 'stk-user11738', 'ME 398', 'info', '{"desc": "السلام عليكم… اخواني ابغاكم تفيدوني… الشركه اسمنت الشرقية اتصلو علي و مقابلتي اليوم في المصنع نفسه في الخرسانيه على تخصص فني ميكانيكة سيارات ولا اعرف شي عنها ابغى تعطوني شي عنها من حيث الرواتب و الروتيشن و كل حاجه علما بأني مقدم فيها من فتره لكن انا عندي شهاده ميكانيكا سيارات و خبره ايضا… و شكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/176178/7", "user": "user11738", "ts": 1566350609000, "tid": 176178, "pn": 7}}', 1566350609000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
